var __erEN = { "\u0441\u0442\u0440. {0}": "p. {0}", "\u0440\u0430\u0437\u0432. {0}": "spr. {0}", "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0445\u043E\u0442\u044F \u0431\u044B \u0434\u0432\u0430 \u0441\u0438\u043C\u0432\u043E\u043B\u0430": "Type at least two characters", "\u0427\u0442\u043E \u043D\u0430\u0439\u0442\u0438 \u0432 \u043A\u043D\u0438\u0433\u0435\u2026": "What to find in the book\u2026", "\u0424\u0438\u043B\u044C\u0442\u0440 \u043F\u043E \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u044E\u2026": "Filter by title\u2026", "\u0412 \u044D\u0442\u043E\u0439 \u043A\u043D\u0438\u0433\u0435 \u043D\u0435 \u043D\u0430\u0448\u043B\u043E\u0441\u044C \u043D\u0438 \u043E\u0433\u043B\u0430\u0432\u043B\u0435\u043D\u0438\u044F, \u043D\u0438 \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043A\u043E\u0432.": "No contents and no headings were found in this book.", "\u041A\u0430\u043A\u0438\u043C \u0446\u0432\u0435\u0442\u043E\u043C \u043F\u043E\u0434\u0441\u0432\u0435\u0442\u0438\u0442\u044C \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442, \u0435\u0441\u043B\u0438 \u0432\u044B \u043D\u0430\u043F\u0438\u0441\u0430\u043B\u0438 \u043A \u043D\u0435\u043C\u0443 \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439, \u043D\u0435 \u0432\u044B\u0431\u0440\u0430\u0432 \u0446\u0432\u0435\u0442 \u0432\u0440\u0443\u0447\u043D\u0443\u044E. \u041A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439 \u043C\u043E\u0436\u0435\u0442 \u0445\u0440\u0430\u043D\u0438\u0442\u044C\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u0438 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0438, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u043E \u0441\u043E\u0437\u0434\u0430\u0451\u0442\u0441\u044F \u0441\u0430\u043C\u043E.": "Which colour to use when you comment on a passage without picking a colour first. A comment can only be stored on a highlight, so one is created for you.", "\u0426\u0432\u0435\u0442 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E": "Default highlight colour", "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439": "Could not save the comment", "\u041D\u0430\u0439\u0434\u0435\u043D\u043E: {0}. \u0421\u043B\u043E\u0432\u043E \u043F\u043E\u0434\u0441\u0432\u0435\u0447\u0435\u043D\u043E \u0432 \u0442\u0435\u043A\u0441\u0442\u0435.": "Found: {0}. The word is highlighted in the text.", "\u0421\u043D\u044F\u0442\u044C \u043F\u043E\u0434\u0441\u0432\u0435\u0442\u043A\u0443": "Clear highlight", "\u041D\u0430\u0439\u0434\u0435\u043D\u043D\u043E\u0435 \u0441\u043B\u043E\u0432\u043E \u043F\u043E\u0434\u0441\u0432\u0435\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u044F\u043C\u043E \u0432 \u0442\u0435\u043A\u0441\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u043D\u0435 \u0438\u0441\u043A\u0430\u0442\u044C \u0435\u0433\u043E \u0433\u043B\u0430\u0437\u0430\u043C\u0438 \u0432 \u0430\u0431\u0437\u0430\u0446\u0435": "The matched word is painted right in the text, so you don't have to hunt for it in the paragraph", "\u041D\u0430\u0439\u0434\u0435\u043D\u043D\u043E\u0435 \u0441\u043B\u043E\u0432\u043E \u043F\u043E\u0434\u0441\u0432\u0435\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0436\u0451\u043B\u0442\u044B\u043C \u043F\u0440\u044F\u043C\u043E \u0432 \u0442\u0435\u043A\u0441\u0442\u0435 \u043A\u043D\u0438\u0433\u0438, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0438\u0441\u043A\u0430\u0442\u044C \u0435\u0433\u043E \u0433\u043B\u0430\u0437\u0430\u043C\u0438 \u0432 \u0430\u0431\u0437\u0430\u0446\u0435 \u043D\u0435 \u043D\u0443\u0436\u043D\u043E. \u0427\u0435\u0440\u0435\u0437 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u0435\u043A\u0443\u043D\u0434 \u043F\u043E\u0434\u0441\u0432\u0435\u0442\u043A\u0430 \u0433\u0430\u0441\u043D\u0435\u0442 \u0441\u0430\u043C\u0430, \u0447\u0442\u043E\u0431\u044B \u043D\u0435 \u043C\u0435\u0448\u0430\u0442\u044C \u0447\u0442\u0435\u043D\u0438\u044E; \u0443\u0431\u0440\u0430\u0442\u044C \u0441\u0440\u0430\u0437\u0443 \u2014 \xAB\u0421\u043D\u044F\u0442\u044C \u043F\u043E\u0434\u0441\u0432\u0435\u0442\u043A\u0443\xBB \u0432 \u043F\u0430\u043D\u0435\u043B\u0438 \u043F\u043E\u0438\u0441\u043A\u0430.": `The matched word is painted yellow right in the book's text \u2014 and stays painted after you close the panel, so you don't have to hunt for it in the paragraph. Turn it off with "Clear highlight" in the search panel.`, "\u041F\u043E\u0438\u0441\u043A \u043F\u043E \u0432\u0441\u0435\u043C\u0443 \u0442\u0435\u043A\u0441\u0442\u0443 \u043A\u043D\u0438\u0433\u0438 \u2014 \u0441\u043F\u0438\u0441\u043E\u043A \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0439 \u0441 \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442\u043E\u043C \u0432\u043E\u043A\u0440\u0443\u0433 \u043A\u0430\u0436\u0434\u043E\u0433\u043E, \u043A\u043B\u0438\u043A \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u0438\u0442 \u043A \u043C\u0435\u0441\u0442\u0443.": "Search across the whole book's text \u2014 a list of matches with context around each, click to jump to that spot.", "\u041F\u043E\u0438\u0441\u043A": "Search", "\u042D\u043A\u0441\u043F\u043E\u0440\u0442 \u0446\u0438\u0442\u0430\u0442 \u0433\u0440\u0443\u043F\u043F\u0438\u0440\u0443\u0435\u0442 \u0438\u0445 \u043F\u043E \u0433\u043B\u0430\u0432\u0430\u043C \u0438 \u043F\u043E\u0434\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u043D\u043E\u043C\u0435\u0440 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B": "Quote export now groups by chapter and labels the page number", "\u041E\u0433\u043B\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0430\u043A\u043E\u043D\u0435\u0446 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u2014 \u0431\u0440\u0430\u043B\u043E \u0434\u0430\u043D\u043D\u044B\u0435, \u043D\u043E \u043D\u0435 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u043B\u043E \u0438\u0445; \u043F\u043E\u0447\u0438\u043D\u0438\u043B, \u0434\u043E\u0431\u0430\u0432\u0438\u043B \u043D\u043E\u043C\u0435\u0440 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B, \u0436\u0438\u0432\u043E\u0439 \u043D\u043E\u043C\u0435\u0440 \u0440\u0430\u0437\u0432\u043E\u0440\u043E\u0442\u0430 \u0438 \u0444\u0438\u043B\u044C\u0442\u0440 \u0434\u043B\u044F \u0434\u043B\u0438\u043D\u043D\u044B\u0445 \u0441\u043F\u0438\u0441\u043A\u043E\u0432": "Contents finally works \u2014 it had the data but never showed it; fixed, plus page numbers, a live spread number and a filter for long lists", "\u041A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439 \u043A \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044E \u2014 \u043A\u043E\u0440\u043E\u0442\u043A\u0430\u044F \u043C\u044B\u0441\u043B\u044C \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043F\u0440\u0438 \u0446\u0438\u0442\u0430\u0442\u0435, \u0430 \u043D\u0435 \u0443\u043B\u0435\u0442\u0430\u0435\u0442 \u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0439 \u0444\u0430\u0439\u043B": "Comment on a highlight \u2014 a short thought stays with the quote instead of flying into a separate file", "\u041F\u043E\u0438\u0441\u043A \u043F\u043E \u0432\u0441\u0435\u0439 \u043A\u043D\u0438\u0433\u0435 \u2014 \u0437\u043D\u0430\u0447\u043E\u043A \u043B\u0443\u043F\u044B \u0432\u0432\u0435\u0440\u0445\u0443 \u0447\u0438\u0442\u0430\u043B\u043A\u0438, \u0441\u043E \u0441\u043F\u0438\u0441\u043A\u043E\u043C \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0439 \u0438 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u043E\u043C \u043A \u043C\u0435\u0441\u0442\u0443": "Search the whole book \u2014 magnifier icon at the top, with a match list and jump-to-spot", "\u0415\u0441\u043B\u0438 \u043F\u0443\u043D\u043A\u0442\u043E\u0432 \u043C\u043D\u043E\u0433\u043E (\u0432 \u0442\u0435\u0445\u043D\u0438\u0447\u0435\u0441\u043A\u0438\u0445 \u043A\u043D\u0438\u0433\u0430\u0445 \u0431\u044B\u0432\u0430\u0435\u0442 300\u2013400), \u0441\u0432\u0435\u0440\u0445\u0443 \u043F\u043E\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043F\u043E\u043B\u0435 \u0444\u0438\u043B\u044C\u0442\u0440\u0430 \u2014 \u043D\u0430\u0447\u043D\u0438\u0442\u0435 \u043F\u0435\u0447\u0430\u0442\u0430\u0442\u044C \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0433\u043B\u0430\u0432\u044B.": "When there are many entries (technical books can have 300\u2013400), a filter field appears at the top \u2014 start typing a chapter name.", "\u0423 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u043F\u0443\u043D\u043A\u0442\u0430 \u2014 \u043D\u043E\u043C\u0435\u0440 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u043A\u043D\u0438\u0433\u0438 \u0438 \u043D\u043E\u043C\u0435\u0440 \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0440\u0430\u0437\u0432\u043E\u0440\u043E\u0442\u0430, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043F\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043D\u0430 \u043B\u0435\u0442\u0443: \u043E\u043D \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0438 \u0448\u0438\u0440\u0438\u043D\u044B \u043E\u043A\u043D\u0430 \u0438\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438 \u0431\u043E\u043A\u043E\u0432\u044B\u0445 \u043F\u0430\u043D\u0435\u043B\u0435\u0439, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0435\u0433\u043E \u043D\u0435\u043B\u044C\u0437\u044F \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C.": "Each entry shows the book's own page number and the current spread number, recomputed live \u2014 it changes with window width or a sidebar opening, so it can't be stored once and reused.", "\u041F\u043B\u0430\u0433\u0438\u043D \u0438\u0449\u0435\u0442 \u043E\u0433\u043B\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0432 \u0442\u0430\u043A\u043E\u043C \u043F\u043E\u0440\u044F\u0434\u043A\u0435: \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0438\u0435 \u0437\u0430\u043A\u043B\u0430\u0434\u043A\u0438 \u0438\u0437 PDF, \u043F\u043E\u0442\u043E\u043C \u0437\u0430\u0433\u043E\u043B\u043E\u0432\u043A\u0438 \u0432 \u0442\u0435\u043A\u0441\u0442\u0435, \u043F\u043E\u0442\u043E\u043C \u043F\u0435\u0447\u0430\u0442\u043D\u043E\u0435 \u0441\u043E\u0434\u0435\u0440\u0436\u0430\u043D\u0438\u0435 \u043A\u043D\u0438\u0433\u0438 (\u0442\u0430 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430 \u0441\u043E \u0441\u043F\u0438\u0441\u043A\u043E\u043C \u0433\u043B\u0430\u0432 \u0438 \u0442\u043E\u0447\u043A\u0430\u043C\u0438), \u0438 \u0432 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u2014 \u0436\u0438\u0440\u043D\u044B\u0435 \u0430\u0431\u0437\u0430\u0446\u044B, \u0435\u0441\u043B\u0438 \u0431\u043E\u043B\u044C\u0448\u0435 \u0437\u0430\u0446\u0435\u043F\u0438\u0442\u044C\u0441\u044F \u043D\u0435 \u0437\u0430 \u0447\u0442\u043E.": "The plugin looks for a contents source in this order: real PDF bookmarks first, then headings in the text, then the book's own printed contents page (the one with the dotted leaders), and as a last resort, bold paragraphs if nothing else is there to go on.", "\u041E\u0433\u043B\u0430\u0432\u043B\u0435\u043D\u0438\u0435: \u043E\u0442\u043A\u0443\u0434\u0430 \u043E\u043D\u043E \u0431\u0435\u0440\u0451\u0442\u0441\u044F": "Contents: where it comes from", "\u0418\u0449\u0435\u0442 \u043F\u043E \u0447\u0430\u0441\u0442\u0438 \u0441\u043B\u043E\u0432\u0430: \u0437\u0430\u043F\u0440\u043E\u0441 \xAB\u0441\u0438\u0441\u0442\u0435\u043C\xBB \u043D\u0430\u0439\u0434\u0451\u0442 \u0438 \xAB\u0441\u0438\u0441\u0442\u0435\u043C\u0430\xBB, \u0438 \xAB\u0441\u0438\u0441\u0442\u0435\u043C\u044B\xBB, \u0438 \xAB\u0441\u0438\u0441\u0442\u0435\u043C\u043D\u044B\u0439\xBB.": 'Matches partial words: searching "system" finds "system", "systems" and "systemic".', "\u041A\u043B\u0438\u043A \u043F\u043E \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0443 \u2014 \u043F\u0435\u0440\u0435\u0445\u043E\u0434 \u043F\u0440\u044F\u043C\u043E \u043A \u044D\u0442\u043E\u043C\u0443 \u043C\u0435\u0441\u0442\u0443, \u043D\u0430 \u043B\u044E\u0431\u043E\u043C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435 \u0438 \u043F\u0440\u0438 \u043B\u044E\u0431\u043E\u0439 \u0448\u0438\u0440\u0438\u043D\u0435 \u043E\u043A\u043D\u0430.": "Click a result to jump straight to that spot, on any device and at any window width.", "\u0417\u043D\u0430\u0447\u043E\u043A \u043B\u0443\u043F\u044B \u0432\u0432\u0435\u0440\u0445\u0443 \u0447\u0438\u0442\u0430\u043B\u043A\u0438 (\u0438\u043B\u0438 \u043A\u043E\u043C\u0430\u043D\u0434\u0430 \xAB\u041F\u043E\u0438\u0441\u043A \u043F\u043E \u043A\u043D\u0438\u0433\u0435\xBB) \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u043E\u0438\u0441\u043A \u043F\u043E \u0432\u0441\u0435\u043C\u0443 \u0442\u0435\u043A\u0441\u0442\u0443 \u2014 \u0441\u043E \u0441\u043F\u0438\u0441\u043A\u043E\u043C \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0439 \u0438 \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442\u043E\u043C \u0442\u0435\u043A\u0441\u0442\u0430 \u0432\u043E\u043A\u0440\u0443\u0433 \u043A\u0430\u0436\u0434\u043E\u0433\u043E.": 'The magnifier icon at the top of the reader (or the "Search the book" command) opens full-text search, with a list of matches and surrounding context for each.', "\u041F\u043E\u0438\u0441\u043A \u043F\u043E \u043A\u043D\u0438\u0433\u0435": "Search the book", "\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u043F\u043E \u043A\u043D\u043E\u043F\u043A\u0435 \u0438\u043B\u0438 Ctrl+Enter. \u0415\u0441\u043B\u0438 \u043E\u0447\u0438\u0441\u0442\u0438\u0442\u044C \u043F\u043E\u043B\u0435 \u2014 \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439 \u0443\u0434\u0430\u043B\u044F\u0435\u0442\u0441\u044F, \u0441\u0430\u043C\u0430 \u0446\u0438\u0442\u0430\u0442\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F.": "Saved with the button or Ctrl+Enter. Clearing the field removes the comment; the quote itself stays.", "\u041F\u0440\u0438\u043C\u0435\u0440: \u043F\u043E\u0434\u0447\u0435\u0440\u043A\u043D\u0443\u043B\u0438 \u0441\u043F\u043E\u0440\u043D\u044B\u0439 \u0442\u0435\u0437\u0438\u0441 \u0438 \u043F\u0440\u0438\u043F\u0438\u0441\u0430\u043B\u0438 \xAB\u0430 \u0432\u043E\u0442 \u0442\u0443\u0442 \u043E\u043D \u0441\u0430\u043C \u0441\u0435\u0431\u0435 \u043F\u0440\u043E\u0442\u0438\u0432\u043E\u0440\u0435\u0447\u0438\u0442\xBB \u2014 \u044D\u0442\u0430 \u0441\u0442\u0440\u043E\u043A\u0430 \u0432\u0438\u0434\u043D\u0430 \u0432 \u043F\u0430\u043D\u0435\u043B\u0438 \xAB\u0412\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F\xBB \u043F\u043E\u0434 \u0446\u0438\u0442\u0430\u0442\u043E\u0439 \u0438 \u043F\u043E\u043F\u0430\u0434\u0430\u0435\u0442 \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438 \u043F\u0440\u0438 \u044D\u043A\u0441\u043F\u043E\u0440\u0442\u0435.": 'Example: you highlight a shaky claim and jot "he contradicts himself right here" \u2014 it shows under the quote in the Highlights panel and travels with it on export.', "\u0423 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u043D\u043E\u0433\u043E \u0442\u0435\u043A\u0441\u0442\u0430, \u043A\u0440\u043E\u043C\u0435 \xAB\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443\xBB, \u0435\u0441\u0442\u044C \u0437\u043D\u0430\u0447\u043E\u043A \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u044F \u2014 \u043A\u043E\u0440\u043E\u0442\u043A\u0430\u044F \u043C\u044B\u0441\u043B\u044C, \u043A\u043E\u0442\u043E\u0440\u0430\u044F \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u041F\u0420\u0418 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0438, \u0430 \u043D\u0435 \u0443\u043B\u0435\u0442\u0430\u0435\u0442 \u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0439 \u0444\u0430\u0439\u043B.": 'Highlighted text has a comment icon besides "Create a note" \u2014 a short thought that stays WITH the highlight instead of flying off into a separate file.', "\u041A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439 \u043A \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044E": "Comment on a highlight", "\u0412 \u0437\u0430\u043C\u0435\u0442\u043A\u0435 \u0446\u0438\u0442\u0430\u0442\u044B \u0441\u043E\u0431\u0440\u0430\u043D\u044B \u043F\u043E \u0433\u043B\u0430\u0432\u0430\u043C, \u0443 \u043A\u0430\u0436\u0434\u043E\u0439 \u2014 \u043D\u043E\u043C\u0435\u0440 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u043A\u043D\u0438\u0433\u0438, \u0430 \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439 (\u0435\u0441\u043B\u0438 \u0432\u044B \u0435\u0433\u043E \u043E\u0441\u0442\u0430\u0432\u0438\u043B\u0438) \u0438\u0434\u0451\u0442 \u043F\u0440\u044F\u043C\u043E \u043F\u043E\u0434 \u0446\u0438\u0442\u0430\u0442\u043E\u0439.": "In the note, quotes are grouped by chapter, each carries the book's page number, and your comment (if you left one) sits right under the quote.", "\u0418\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u044F \u0432\u044B\u0440\u043E\u0441\u043B\u0430 \u0434\u043E 21 \u044D\u043A\u0440\u0430\u043D\u0430 \u2014 \u0442\u0435\u043F\u0435\u0440\u044C \u0440\u0430\u0437\u0431\u0438\u0440\u0430\u0435\u0442 \u043A\u0430\u0436\u0434\u0443\u044E \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0443 \u0441 \u043F\u0440\u0438\u043C\u0435\u0440\u0430\u043C\u0438": "The guide has grown \u2014 it now walks through every setting with examples", "\u0420\u0435\u0436\u0438\u043C \u0434\u043B\u044F e-ink \u0447\u0438\u0442\u0430\u043B\u043E\u043A: \u0431\u0435\u0437 \u0430\u043D\u0438\u043C\u0430\u0446\u0438\u0439 \u0438 \u0442\u0435\u043D\u0435\u0439, \u0447\u0438\u0441\u0442\u044B\u0439 \u0447\u0451\u0440\u043D\u044B\u0439 \u043D\u0430 \u0431\u0435\u043B\u043E\u043C, \u043A\u0440\u0443\u043F\u043D\u0435\u0435 \u043A\u043D\u043E\u043F\u043A\u0438": "E-ink reader mode: no animations or shadows, pure black on white, bigger buttons", "\u0412\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u043F\u0435\u0440\u0435\u043D\u043E\u0441\u044F\u0442\u0441\u044F \u0432\u044B\u0431\u043E\u0440\u043E\u0447\u043D\u043E: \u0433\u0430\u043B\u043E\u0447\u043A\u0438, \xAB\u0432\u044B\u0434\u0435\u043B\u0438\u0442\u044C \u0432\u0441\u0435\xBB, \xAB\u0442\u043E\u043B\u044C\u043A\u043E \u043D\u043E\u0432\u044B\u0435\xBB \u2014 \u0443\u0436\u0435 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0451\u043D\u043D\u043E\u0435 \u043D\u0435 \u0437\u0430\u0434\u0432\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044F": 'Highlights are exported selectively: tick boxes, "select all", "new only" \u2014 nothing already copied gets duplicated', "\u0417\u0430\u043C\u0435\u0442\u043A\u0443 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u043C\u043E\u0436\u043D\u043E \u0441\u0440\u0430\u0437\u0443 \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u044C \u0432 \u043D\u0443\u0436\u043D\u0443\u044E \u043F\u0430\u043F\u043A\u0443 \u0438 \u043F\u0440\u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0442\u0435\u0433\u0438": "A note made from a highlight can go straight into the folder you want, with tags", "\u041A\u0430\u0440\u0442\u0438\u043D\u043A\u0438 \u0438\u0437 \u043A\u043D\u0438\u0433 \u0442\u0435\u043F\u0435\u0440\u044C \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0441\u0440\u0430\u0437\u0443 \u2014 \u0440\u0430\u043D\u044C\u0448\u0435 \u0438\u0445 \u043F\u0440\u0438\u0445\u043E\u0434\u0438\u043B\u043E\u0441\u044C \u0438\u0441\u043A\u0430\u0442\u044C \u0432 \u0434\u0440\u0443\u0433\u043E\u0439 \u0447\u0438\u0442\u0430\u043B\u043A\u0435": "Pictures now show up straight away \u2014 previously you had to open another reader to find them", "\u041A\u0430\u0440\u0442\u0438\u043D\u043A\u0438 \u0432 \u043A\u043D\u0438\u0433\u0430\u0445": "Pictures in books", "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F: \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435, \u043F\u0430\u043F\u043A\u0430, \u0442\u0435\u0433\u0438": "A note from a highlight: title, folder, tags", "\u041F\u0430\u043F\u043A\u0430 \u0438 \u0442\u0435\u0433\u0438 \u0437\u0430\u043F\u043E\u043C\u043D\u044F\u0442\u0441\u044F \u0434\u043B\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0437\u0430\u043C\u0435\u0442\u043A\u0438. \u0421\u0430\u043C \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442 \u043F\u043E\u043F\u0430\u0434\u0451\u0442 \u0432 \u0442\u0435\u043A\u0441\u0442 \u0446\u0435\u043B\u0438\u043A\u043E\u043C \u2014 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u043D\u0430 \u044D\u0442\u043E \u043D\u0435 \u0432\u043B\u0438\u044F\u0435\u0442.": "The folder and tags are remembered for the next note. The passage itself goes into the note in full \u2014 the title does not affect that.", "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440: \u0438\u0434\u0435\u0438, \u043F\u0441\u0438\u0445\u043E\u043B\u043E\u0433\u0438\u044F": "For example: ideas, psychology", "\u0422\u0435\u0433\u0438": "Tags", "\u041D\u0430\u0437\u0432\u0430\u043D\u0438\u0435": "Title", "\u041D\u043E\u0432\u0430\u044F \u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F": "New note from a highlight", "\u0414\u043B\u044F Obsidian \u043D\u0430 Android-\u0447\u0438\u0442\u0430\u043B\u043A\u0435 \u0441 \u044D\u043B\u0435\u043A\u0442\u0440\u043E\u043D\u043D\u044B\u043C\u0438 \u0447\u0435\u0440\u043D\u0438\u043B\u0430\u043C\u0438. \u0423\u0431\u0438\u0440\u0430\u0435\u0442 \u0430\u043D\u0438\u043C\u0430\u0446\u0438\u0438, \u043F\u043B\u0430\u0432\u043D\u044B\u0435 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u044B, \u0442\u0435\u043D\u0438 \u0438 \u0440\u0430\u0437\u043C\u044B\u0442\u0438\u0435 \u2014 \u043E\u043D\u0438 \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442 \u043D\u0430 \u0442\u0430\u043A\u043E\u043C \u044D\u043A\u0440\u0430\u043D\u0435 \u0441\u043B\u0435\u0434\u044B. \u0427\u0438\u0441\u0442\u044B\u0439 \u0447\u0451\u0440\u043D\u044B\u0439 \u043D\u0430 \u0431\u0435\u043B\u043E\u043C, \u0436\u0451\u0441\u0442\u043A\u0438\u0435 \u0440\u0430\u043C\u043A\u0438, \u043A\u0440\u0443\u043F\u043D\u0435\u0435 \u043A\u043D\u043E\u043F\u043A\u0438, \u043B\u0438\u0441\u0442\u0430\u043D\u0438\u0435 \u0431\u0435\u0437 \u0441\u043A\u043E\u043B\u044C\u0436\u0435\u043D\u0438\u044F.": "For Obsidian on an Android e-ink reader. Removes animations, fades, shadows and blur \u2014 they leave ghosting on such a screen. Pure black on white, hard borders, bigger buttons, page turns that jump instead of sliding.", "\u0420\u0435\u0436\u0438\u043C \u0434\u043B\u044F e-ink \u0447\u0438\u0442\u0430\u043B\u043E\u043A": "E-ink reader mode", "\u041F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "Move highlights into notes", "\u0418\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u044F \u043F\u043E \u043F\u043B\u0430\u0433\u0438\u043D\u0443": "Plugin guide", "\u0418\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u044F: \u0440\u0430\u0437\u0431\u043E\u0440 \u0432\u0441\u0435\u0445 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043A \u043F\u043E \u0448\u0430\u0433\u0430\u043C": "Guide: every setting, step by step", "\u041A\u043E\u043C\u0430\u043D\u0434\u044B \u0438 \u0433\u043E\u0440\u044F\u0447\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448\u0438": "Commands and hotkeys", "\u041A\u0430\u043A \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "Moving highlights into notes", "\u0412\u043A\u043B\u0430\u0434\u043A\u0430 \xAB\u0414\u0430\u043D\u043D\u044B\u0435\xBB: \u0433\u0434\u0435 \u0447\u0442\u043E \u043B\u0435\u0436\u0438\u0442": "The Data tab: where things live", "\u0412\u043A\u043B\u0430\u0434\u043A\u0430 \xAB\u041F\u0435\u0440\u0435\u0432\u043E\u0434\xBB": "The Translate tab", "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u043A\u043D\u0438\u0433\u0438 \u0438 \u0448\u0430\u0431\u043B\u043E\u043D": "The book note and the template", "\u041A\u0443\u0434\u0430 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "Where notes are filed", "\u0412\u043A\u043B\u0430\u0434\u043A\u0430 \xAB\u0417\u0430\u043C\u0435\u0442\u043A\u0438\xBB: \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "The Notes tab: note titles", "\xAB\u041F\u043E\u0433\u0440\u0443\u0436\u0435\u043D\u0438\u0435\xBB \u0438 \u0446\u0435\u043B\u044C \u0447\u0442\u0435\u043D\u0438\u044F": "Immersive mode and the reading goal", "\xAB\u0412\u044B\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u043D\u0438\u0435\xBB \u0438 \xAB\u041F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0442\u0435\u043A\u0441\u0442\u0430\xBB": "Alignment and text position", "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \xAB\u041B\u0438\u0441\u0442\u0430\u043D\u0438\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\xBB": 'The "Turning pages" setting', "\u0412\u043A\u043B\u0430\u0434\u043A\u0430 \xAB\u0427\u0442\u0435\u043D\u0438\u0435\xBB: \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043A\u0430": "The Reading tab: statistics", "\u0414\u0430\u043B\u044C\u0448\u0435 \u2014 \u0440\u0430\u0437\u0431\u043E\u0440 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043A": "Next: a tour of the settings", "\u0427\u0442\u043E \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0442\u0438 \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0443": "What to copy into the note", "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \xAB{0}\xBB \u2014 {1} \u0443\u0436\u0435 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0435\u043D\u043E, \u043E\u0442\u043C\u0435\u0447\u0435\u043D\u043E {2} \u043D\u043E\u0432\u044B\u0445": 'Note "{0}" \u2014 {1} already there, {2} new ones ticked', "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \xAB{0}\xBB \u2014 \u0432\u0441\u0435 {1} \u0435\u0449\u0451 \u043D\u0435 \u043F\u0435\u0440\u0435\u043D\u0435\u0441\u0435\u043D\u044B": 'Note "{0}" \u2014 none of the {1} are there yet', "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u043A\u043D\u0438\u0433\u0438 \u043D\u0435 \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u043D\u0430 \u2014 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0435 \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "No book note linked \u2014 separate notes only", "\u0412\u044B\u0434\u0435\u043B\u0438\u0442\u044C \u0432\u0441\u0435": "Select all", "\u0421\u043D\u044F\u0442\u044C \u0432\u0441\u0435": "Clear all", "\u0422\u043E\u043B\u044C\u043A\u043E \u043D\u043E\u0432\u044B\u0435": "New only", "\u0443\u0436\u0435 \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0435": "already in the note", "\u041E\u0442\u043C\u0435\u0447\u0435\u043D\u043E: {0} \u0438\u0437 {1}": "Ticked: {0} of {1}", "\u0412 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438": "Into the book note", "\u041E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u0437\u0430\u043C\u0435\u0442\u043A\u0430\u043C\u0438": "As separate notes", "\u042D\u0442\u0430 \u0446\u0438\u0442\u0430\u0442\u0430 \u0443\u0436\u0435 \u0435\u0441\u0442\u044C \u0432 \xAB{0}\xBB": 'That quote is already in "{0}"', "\u0412\u0441\u0435 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u0446\u0438\u0442\u0430\u0442\u044B \u0443\u0436\u0435 \u0435\u0441\u0442\u044C \u0432 \xAB{0}\xBB": 'All the selected quotes are already in "{0}"', "\u0414\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043E \u0432 \xAB{0}\xBB: {1}, \u043F\u0440\u043E\u043F\u0443\u0449\u0435\u043D\u043E \u0443\u0436\u0435 \u0438\u043C\u0435\u0432\u0448\u0438\u0445\u0441\u044F: {2}": 'Added to "{0}": {1}; skipped as already present: {2}', "\u041D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u043F\u043E\u0434\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438: \u043F\u0435\u0440\u0432\u043E\u0435 \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442\u0430 \u0438\u043B\u0438 \u0435\u0433\u043E \u043D\u0430\u0447\u0430\u043B\u043E \u043F\u043E \u0433\u0440\u0430\u043D\u0438\u0446\u0435 \u0441\u043B\u043E\u0432\u0430. \u0412\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043E \u2014 \u0432 \u0438\u043C\u044F \u0444\u0430\u0439\u043B\u0430 \u0438\u0434\u0451\u0442 \u0432\u0435\u0441\u044C \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442, \u043A\u0430\u043A \u0440\u0430\u043D\u044C\u0448\u0435.": "The title is chosen automatically: the passage's first sentence, or its opening cut on a word boundary. Off \u2014 the whole passage goes into the filename, as before.", "\u041A\u043E\u0440\u043E\u0442\u043A\u0438\u0435 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u044F \u0431\u0435\u0437 \u0432\u043E\u043F\u0440\u043E\u0441\u043E\u0432": "Short titles, no questions", "\u041F\u0435\u0440\u0435\u0434 \u0441\u043E\u0437\u0434\u0430\u043D\u0438\u0435\u043C \u0437\u0430\u043C\u0435\u0442\u043A\u0438 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u043E\u043A\u043D\u043E \u0441 \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u043C \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435\u043C \u2014 \u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0438\u0441\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0438\u043B\u0438 \u043E\u0434\u043D\u043E\u0439 \u043A\u043D\u043E\u043F\u043A\u043E\u0439 \u0432\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442 \u0446\u0435\u043B\u0438\u043A\u043E\u043C. \u0411\u0435\u0437 \u044D\u0442\u043E\u0433\u043E \u0438\u043C\u044F \u0444\u0430\u0439\u043B\u0430 \u0431\u0435\u0440\u0451\u0442\u0441\u044F \u0438\u0437 \u0441\u0430\u043C\u043E\u0433\u043E \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442\u0430 \u0438 \u0432\u044B\u0445\u043E\u0434\u0438\u0442 \u043E\u0447\u0435\u043D\u044C \u0434\u043B\u0438\u043D\u043D\u044B\u043C.": "Before a note is created from a highlight, a dialog offers a short title you can edit, or insert the whole passage with one click. Without it the filename is taken from the passage itself and comes out very long.", "\u0421\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0442\u044C \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "Ask for the note title", "\u041E\u0442\u043C\u0435\u043D\u0430": "Cancel", "\u0421\u0430\u043C \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442 \u043F\u043E\u043F\u0430\u0434\u0451\u0442 \u0432 \u0442\u0435\u043A\u0441\u0442 \u0437\u0430\u043C\u0435\u0442\u043A\u0438 \u0446\u0435\u043B\u0438\u043A\u043E\u043C \u2014 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u043D\u0430 \u044D\u0442\u043E \u043D\u0435 \u0432\u043B\u0438\u044F\u0435\u0442.": "The passage itself goes into the note in full \u2014 the title does not affect that.", "\u0412\u0437\u044F\u0442\u044C \u0432\u0435\u0441\u044C \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442 \u043A\u0430\u043A \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435": "Use the whole passage as the title", "\u041A\u0430\u043A\u0443\u044E \u043A\u043D\u0438\u0433\u0443 \u043E\u0442\u043A\u0440\u044B\u0442\u044C?": "Which book do you want to open?", "\u041A\u043D\u0438\u0433\u0430 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u0430: {0}": "Book not found: {0}", "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u043A\u043D\u0438\u0433\u0443: {0}": "Open book: {0}", "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u043A\u043D\u0438\u0433\u0443\u2026": "Open a book\u2026", "\u041F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u0447\u0442\u0435\u043D\u0438\u0435 (\u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u043A\u043D\u0438\u0433\u0430)": "Continue reading (last book)", "\u041F\u0435\u0440\u0435\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u043F\u0440\u0438 \u0441\u0432\u043E\u0440\u0430\u0447\u0438\u0432\u0430\u043D\u0438\u0438 \u043F\u0430\u043D\u0435\u043B\u0435\u0439 \u0441\u0442\u0430\u043B\u043E \u043F\u043B\u0430\u0432\u043D\u044B\u043C, \u0430 \u043D\u0435 \u0440\u044B\u0432\u043A\u043E\u043C": "Re-layout when sidebars open or close now fades instead of jumping", "\u0421\u0442\u0440\u043E\u043A\u0438 \u0437\u0430\u043F\u043E\u043B\u043D\u044F\u044E\u0442 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u2014 \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435\u0442 \u043F\u0443\u0441\u0442\u044B\u0445 \u043C\u0435\u0441\u0442 \u0432\u043D\u0438\u0437\u0443 \u043A\u043E\u043B\u043E\u043D\u043A\u0438": "Lines fill the page to the bottom \u2014 no more blank gaps at the foot of a column", "\u041B\u0438\u0441\u0442\u0430\u043D\u0438\u0435 \u0441\u0442\u0440\u043E\u0433\u043E \u0432\u043F\u0440\u0430\u0432\u043E, \u0431\u0435\u0437 \u0441\u044A\u0435\u0437\u0436\u0430\u043D\u0438\u044F \u0432 \u0443\u0433\u043E\u043B, \u0438 \u0442\u0435\u043A\u0441\u0442 \u0441\u0442\u0430\u043B \u0447\u0451\u0442\u043A\u0438\u043C": "Page turns go straight sideways instead of drifting into the corner, and text is sharp", "\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043A\u0430 \u0447\u0442\u0435\u043D\u0438\u044F: \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0432\u0441\u0435\u0433\u043E \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u043D\u043E, \u0441\u0435\u0440\u0438\u044F \u0434\u043D\u0435\u0439 \u0438 \u0433\u0440\u0430\u0444\u0438\u043A \u0437\u0430 \u0434\u0432\u0435 \u043D\u0435\u0434\u0435\u043B\u0438": "Reading stats: all-time total, day streak and a two-week chart", "\u041A\u043D\u0438\u0433\u0443 \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043A\u043E\u043C\u0430\u043D\u0434\u043E\u0439 \u2014 \u0441\u0432\u043E\u044F \u043A\u043E\u043C\u0430\u043D\u0434\u0430 \u0438 \u0433\u043E\u0440\u044F\u0447\u0430\u044F \u043A\u043B\u0430\u0432\u0438\u0448\u0430 \u043D\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u043A\u043D\u0438\u0433\u0443": "Open a book by command \u2014 each book gets its own command and hotkey", "\u0421\u043A\u043E\u043B\u044C\u043A\u043E \u043C\u0438\u043D\u0443\u0442 \u0432 \u0434\u0435\u043D\u044C \u0432\u044B \u0445\u043E\u0442\u0438\u0442\u0435 \u0447\u0438\u0442\u0430\u0442\u044C. \u041F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u0437\u0430 \u0441\u0435\u0433\u043E\u0434\u043D\u044F \u2014 \u0432 \u043A\u0430\u0440\u0442\u043E\u0447\u043A\u0435 \u0432\u0432\u0435\u0440\u0445\u0443 \u044D\u0442\u043E\u0439 \u0432\u043A\u043B\u0430\u0434\u043A\u0438.": "How many minutes a day you want to read. Today's progress is in the card at the top of this tab.", "\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0443 \u0438 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u0442\u0430\u0439\u043C\u0435\u0440 \u25B6 \u2014 \u0437\u0434\u0435\u0441\u044C \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u0438\u0441\u0442\u043E\u0440\u0438\u044F \u0447\u0442\u0435\u043D\u0438\u044F.": "Open a book and start the timer \u25B6 \u2014 your reading history will appear here.", "14 \u0434\u043D\u0435\u0439 \u043D\u0430\u0437\u0430\u0434": "14 days ago", "\u043B\u0443\u0447\u0448\u0438\u0439 \u0434\u0435\u043D\u044C": "best day", "\u0432 \u0441\u0440\u0435\u0434\u043D\u0435\u043C \u0437\u0430 \u0434\u0435\u043D\u044C": "daily average", "\u0434\u043D\u0435\u0439 \u0441 \u043A\u043D\u0438\u0433\u043E\u0439": "days with a book", "\u0441\u0435\u0433\u043E\u0434\u043D\u044F": "today", "{0} \u0434\u043D. \u043F\u043E\u0434\u0440\u044F\u0434": "{0}-day streak", "\u0437\u0430 \u0432\u0441\u0451 \u0432\u0440\u0435\u043C\u044F \u0441 \u043A\u043D\u0438\u0433\u0430\u043C\u0438": "all-time with books", "{0} \u0434": "{0} d", "{0} \u0434 {1} \u0447": "{0} d {1} h", "{0} \u0447": "{0} h", "\u043C\u0435\u043D\u044C\u0448\u0435 \u043C\u0438\u043D\u0443\u0442\u044B": "less than a minute", "\u041F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043D\u0430 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0435": "Position on the page", "\u041F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0442\u0435\u043A\u0441\u0442\u0430 \u043D\u0430 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0435": "Text position on the page", "\u0421\u0432\u0435\u0440\u0445\u0443": "Top", "\u0421\u043D\u0438\u0437\u0443": "Bottom", "\u041A\u0443\u0434\u0430 \u043F\u0440\u0438\u0436\u0438\u043C\u0430\u0442\u044C \u0442\u0435\u043A\u0441\u0442, \u0435\u0441\u043B\u0438 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430 \u0437\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u0430 \u043D\u0435 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u2014 \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0432 \u043A\u043E\u043D\u0446\u0435 \u0433\u043B\u0430\u0432\u044B.": "Where to place the text when a page isn't filled \u2014 at the end of a chapter, for instance.", "\u0415\u0441\u043B\u0438 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430 \u0437\u0430\u043F\u043E\u043B\u043D\u0435\u043D\u0430 \u043D\u0435 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 (\u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0432 \u043A\u043E\u043D\u0446\u0435 \u0433\u043B\u0430\u0432\u044B), \u0442\u0435\u043A\u0441\u0442 \u043C\u043E\u0436\u043D\u043E \u043D\u0435 \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0442\u044C \u043F\u0440\u0438\u0436\u0430\u0442\u044B\u043C \u043A \u0432\u0435\u0440\u0445\u0443. \u041C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0438 \u043D\u0430 \u043B\u0435\u0442\u0443 \u2014 \u0432 \u043F\u0430\u043D\u0435\u043B\u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043A \u0447\u0442\u0435\u043D\u0438\u044F.": "When a page isn't filled (at the end of a chapter, for instance), the text needn't stay pinned to the top. Can also be changed on the fly from the reading-settings panel.", "\u0427\u0442\u0435\u043D\u0438\u0435": "Reading", "\u0417\u0430\u043C\u0435\u0442\u043A\u0438": "Notes", "\u0414\u0430\u043D\u043D\u044B\u0435": "Data", "\u041E \u043F\u043B\u0430\u0433\u0438\u043D\u0435": "About", "\u041E\u0447\u0438\u0441\u0442\u043A\u0430": "Cleanup", "\u0428\u0430\u0431\u043B\u043E\u043D": "Template", "\u0426\u0435\u043B\u044C \u0447\u0442\u0435\u043D\u0438\u044F": "Reading goal", "\u0427\u0442\u043E \u043D\u043E\u0432\u043E\u0433\u043E": "What's new", "\u041F\u043E\u043A\u0430\u0437\u0430\u0442\u044C": "Show", "\u0421\u043F\u0438\u0441\u043E\u043A \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0439 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0445 \u0432\u0435\u0440\u0441\u0438\u0439.": "Changes from recent versions.", "<b>Book Reader</b> \u2014 \u0432\u0435\u0440\u0441\u0438\u044F {0}. \u0410\u0432\u0442\u043E\u0440: Elton Labs.": "<b>Book Reader</b> \u2014 version {0}. By Elton Labs.", "\u0428\u0440\u0438\u0444\u0442, \u0440\u0430\u0437\u043C\u0435\u0440 \u0438 \u043C\u0435\u0436\u0441\u0442\u0440\u043E\u0447\u043D\u044B\u0439 \u0438\u043D\u0442\u0435\u0440\u0432\u0430\u043B \u043D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u043F\u0440\u044F\u043C\u043E \u0432 \u043A\u043D\u0438\u0433\u0435 \u2014 \u0438\u043A\u043E\u043D\u043A\u0430 \u043F\u043E\u043B\u0437\u0443\u043D\u043A\u043E\u0432 \u0432\u0432\u0435\u0440\u0445\u0443 \u0447\u0438\u0442\u0430\u043B\u043A\u0438.": "Font, size and line spacing are set inside the book \u2014 the sliders icon at the top of the reader.", "\u0414\u043E\u043F. \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438": "More settings", "\u041F\u0430\u043C\u044F\u0442\u044C \u043E \u043A\u043D\u0438\u0433\u0430\u0445": "What the reader remembers", "\u0417\u0430\u0431\u044B\u0442\u044C \u0432\u0441\u0435 \u043A\u043D\u0438\u0433\u0438": "Forget all books", "\u0422\u043E\u0447\u043D\u043E \u0437\u0430\u0431\u044B\u0442\u044C?": "Really forget?", "\u0413\u043E\u0442\u043E\u0432\u043E \u2014 \u0447\u0438\u0442\u0430\u043B\u043A\u0430 \u0441\u043D\u043E\u0432\u0430 \u0441\u043F\u0440\u043E\u0441\u0438\u0442 \u043F\u0440\u043E \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043F\u0440\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438 \u043A\u043D\u0438\u0433\u0438": "Done \u2014 the reader will ask about a note again when you open a book", "\u0417\u0430\u0431\u044B\u0442\u044C \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u044D\u0442\u043E\u0439 \u043A\u043D\u0438\u0433\u0438": "Forget this book's settings", "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043A\u043D\u0438\u0433\u0438 \u0441\u0431\u0440\u043E\u0448\u0435\u043D\u044B \u2014 \u043E\u043A\u043D\u043E \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u043F\u0440\u0438 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u043C \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438": "Book settings cleared \u2014 the setup screen will appear next time you open it", "\u041A\u043D\u0438\u0433: {0}. \u041F\u0440\u0438\u0432\u044F\u0437\u0430\u043D\u043D\u044B\u0435 \u0437\u0430\u043C\u0435\u0442\u043A\u0438, \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0438, \u0448\u0430\u0431\u043B\u043E\u043D\u044B \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0445 \u043A\u043D\u0438\u0433 \u0438 \u043E\u0442\u043C\u0435\u0442\u043A\u0438 \xAB\u043F\u0440\u043E \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u0443\u0436\u0435 \u0441\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u043B\u0438\xBB. \u0421\u0430\u043C\u0438 \u0437\u0430\u043C\u0435\u0442\u043A\u0438 \u041D\u0415 \u0443\u0434\u0430\u043B\u044F\u044E\u0442\u0441\u044F \u2014 \u0447\u0438\u0442\u0430\u043B\u043A\u0430 \u043F\u0440\u043E\u0441\u0442\u043E \u0437\u0430\u0431\u044B\u0432\u0430\u0435\u0442 \u0441\u0432\u044F\u0437\u0438 \u0438 \u0441\u043F\u0440\u043E\u0441\u0438\u0442 \u043F\u0440\u043E \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u0437\u0430\u043D\u043E\u0432\u043E \u043F\u0440\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438 \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u043D\u0438\u0433\u0438.": 'Books: {0}. Linked notes, categories, per-book templates and the "already asked about a note" marks. The notes themselves are NOT deleted \u2014 the reader just forgets the links and will ask about a note again when you open each book.', "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u043A\u043D\u0438\u0433\u0438 \u0434\u043B\u044F \u0441\u0441\u044B\u043B\u043E\u043A": "Book note for links", "\u0428\u0430\u0431\u043B\u043E\u043D \u0434\u043B\u044F \u044D\u0442\u043E\u0439 \u043A\u043D\u0438\u0433\u0438": "Template for this book", "Book Reader \u043E\u0431\u043D\u043E\u0432\u043B\u0451\u043D \u0434\u043E {0}": "Book Reader updated to {0}", "\u041F\u043E\u043D\u044F\u0442\u043D\u043E": "Got it", "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0438\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u044E": "Open the guide", "\u0420\u0430\u0441\u0448\u0438\u0440\u0435\u043D\u043D\u044B\u0435": "Advanced", "\u041A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u044F": "Category", "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440: \u041F\u0441\u0438\u0445\u043E\u043B\u043E\u0433\u0438\u044F, \u0411\u0438\u0437\u043D\u0435\u0441": "e.g. Psychology, Business", "\u0416\u0430\u043D\u0440 \u0438\u043B\u0438 \u0442\u0435\u043C\u0430 \u2014 \u043F\u043E \u043D\u0435\u0439 \u043A\u043D\u0438\u0433\u0438 \u0433\u0440\u0443\u043F\u043F\u0438\u0440\u0443\u044E\u0442\u0441\u044F \u0432 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0435. \u041D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u2014 \u0447\u0435\u0440\u0435\u0437 \u0437\u0430\u043F\u044F\u0442\u0443\u044E. \u041C\u043E\u0436\u043D\u043E \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u043F\u0443\u0441\u0442\u044B\u043C.": "Genre or topic \u2014 books are grouped by it in the library. Separate several with commas. Can be left empty.", "\u0416\u0430\u043D\u0440 \u0438\u043B\u0438 \u0442\u0435\u043C\u0430 \u2014 \u043F\u043E \u043D\u0435\u0439 \u043A\u043D\u0438\u0433\u0438 \u0433\u0440\u0443\u043F\u043F\u0438\u0440\u0443\u044E\u0442\u0441\u044F \u0432 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0435. \u041D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u2014 \u0447\u0435\u0440\u0435\u0437 \u0437\u0430\u043F\u044F\u0442\u0443\u044E. \u041F\u0443\u0441\u0442\u043E \u2014 \u0431\u0435\u0437 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0438.": "Genre or topic \u2014 books are grouped by it in the library. Separate several with commas. Empty means no category.", "\u0426\u0438\u0442\u0430\u0442\u044B \u0438 \u043C\u044B\u0441\u043B\u0438 \u0438\u0437 \u043A\u043D\u0438\u0433\u0438 \u0431\u0443\u0434\u0443\u0442 \u0441\u0441\u044B\u043B\u0430\u0442\u044C\u0441\u044F \u043D\u0430 \u044D\u0442\u0443 \u0437\u0430\u043C\u0435\u0442\u043A\u0443.": "Quotes and thoughts from this book will link to this note.", "\u041F\u043E\u0438\u0441\u043A \u0437\u0430\u043C\u0435\u0442\u043A\u0438\u2026": "Search notes\u2026", "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443\u2026": "Create a note\u2026", "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443": "Create note", "\u2190 \u041D\u0430\u0437\u0430\u0434": "\u2190 Back", "\u0412 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 \u043F\u043E\u043A\u0430 \u043D\u0435\u0442 \u0437\u0430\u043C\u0435\u0442\u043E\u043A \u2014 \u0441\u043E\u0437\u0434\u0430\u0439\u0442\u0435 \u043D\u043E\u0432\u0443\u044E \u043D\u0438\u0436\u0435": "No notes in the vault yet \u2014 create one below", "\u041D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u043E": "Nothing found", "\u0412\u0441\u0435": "All", "\u0427\u0438\u0442\u0430\u044E": "Reading", "\u041D\u0435 \u043D\u0430\u0447\u0430\u0442\u044B\u0435": "Not started", "\u041F\u0440\u043E\u0447\u0438\u0442\u0430\u043D\u043E": "Finished", "\u0411\u0435\u0437 \u043F\u0430\u043F\u043A\u0438": "No folder", "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u0434\u043B\u044F \u043A\u043D\u0438\u0433\u0438": "A note for this book", "\u041A\u0443\u0434\u0430 \u0441\u043E\u0431\u0438\u0440\u0430\u0442\u044C \u0446\u0438\u0442\u0430\u0442\u044B \u0438 \u043C\u044B\u0441\u043B\u0438 \u0438\u0437 \u044D\u0442\u043E\u0439 \u043A\u043D\u0438\u0433\u0438? \u0412\u044B\u0434\u0435\u043B\u0435\u043D\u043D\u044B\u0435 \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442\u044B \u0431\u0443\u0434\u0443\u0442 \u0441\u0441\u044B\u043B\u0430\u0442\u044C\u0441\u044F \u043D\u0430 \u044D\u0442\u0443 \u0437\u0430\u043C\u0435\u0442\u043A\u0443.": "Where should quotes and thoughts from this book go? Highlights will link back to this note.", "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u0434\u043B\u044F \u043A\u043D\u0438\u0433\u0438": "Create a note for this book", "\u041D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "Note name", "\u041F\u0430\u043F\u043A\u0430": "Folder", "\u041A\u043E\u0440\u0435\u043D\u044C \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0430": "Vault root", "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u0438 \u043D\u0430\u0447\u0430\u0442\u044C \u0447\u0438\u0442\u0430\u0442\u044C": "Create and start reading", "\u0438\u043B\u0438": "or", "\u0412\u044B\u0431\u0440\u0430\u0442\u044C \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0449\u0443\u044E \u0437\u0430\u043C\u0435\u0442\u043A\u0443": "Pick an existing note", "\u0427\u0438\u0442\u0430\u0442\u044C \u0431\u0435\u0437 \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "Read without a note", "\u0412 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 \u043F\u043E\u043A\u0430 \u043D\u0435\u0442 \u0437\u0430\u043C\u0435\u0442\u043E\u043A \u2014 \u0441\u043E\u0437\u0434\u0430\u0439\u0442\u0435 \u043D\u043E\u0432\u0443\u044E": "There are no notes in the vault yet \u2014 create one", "\u0411\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u0441\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0442\u044C \u2014 \u0441\u043E\u0437\u0434\u0430\u0432\u0430\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u043D\u0438\u0433\u0438 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438": "Don't ask again \u2014 create a note for every book automatically", "\u042D\u0442\u043E \u0432\u0441\u0435\u0433\u0434\u0430 \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043C\u0435\u043D\u044F\u0442\u044C \u043F\u043E\u0442\u043E\u043C \u2014 \u043A\u043D\u043E\u043F\u043A\u0430 (i) \u0432\u0432\u0435\u0440\u0445\u0443 \u0447\u0438\u0442\u0430\u043B\u043A\u0438 \u0438\u043B\u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043F\u043B\u0430\u0433\u0438\u043D\u0430.": "You can change this later \u2014 the (i) button at the top of the reader, or the plugin settings.", "+ \u0421\u043E\u0437\u0434\u0430\u0442\u044C \u043D\u043E\u0432\u0443\u044E": "+ Create new", "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u0441 \u044D\u0442\u043E\u0439 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B": "Note from this page", "{0} \u2014 \u0441\u0442\u0440. {1}": "{0} \u2014 p. {1}", "\u2014 \u0438\u0437 [[{0}]], \u0441\u0442\u0440. {1}": "\u2014 from [[{0}]], p. {1}", "> *(\u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430-\u0441\u043A\u0430\u043D \u2014 \u0442\u0435\u043A\u0441\u0442\u0430 \u0434\u043B\u044F \u0446\u0438\u0442\u0430\u0442\u044B \u043D\u0435\u0442, \u0432\u043F\u0438\u0448\u0438\u0442\u0435 \u0441\u0432\u043E\u0438\u043C\u0438 \u0441\u043B\u043E\u0432\u0430\u043C\u0438)*": "> *(scanned page \u2014 no text to quote, write it in your own words)*", "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u0441\u043E\u0437\u0434\u0430\u043D\u0430: {0}": "Note created: {0}", "\u041F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C \u043A\u0430\u0440\u0442\u0438\u043D\u043A\u0438 \u0438\u0437 \u043A\u043D\u0438\u0433\u0438": "Show pictures from the book", "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0412\u042B\u041A\u041B: \u0435\u0441\u043B\u0438 \u0438\u0437 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u0438\u0437\u0432\u043B\u0435\u043A\u0430\u0435\u0442\u0441\u044F \u0442\u0435\u043A\u0441\u0442 \u2014 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0438\u0441\u0442\u044B\u0439 \u0442\u0435\u043A\u0441\u0442. \u0412\u043A\u043B\u044E\u0447\u0438\u0442\u0435, \u0447\u0442\u043E\u0431\u044B \u043D\u0430\u0434 \u0442\u0435\u043A\u0441\u0442\u043E\u043C \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u043B\u0438\u0441\u044C \u0438\u043B\u043B\u044E\u0441\u0442\u0440\u0430\u0446\u0438\u0438, \u0441\u0445\u0435\u043C\u044B \u0438 \u0433\u0440\u0430\u0444\u0438\u043A\u0438: \u0432\u044B\u0440\u0435\u0437\u0430\u044E\u0442\u0441\u044F \u0441\u0430\u043C\u0438 \u043A\u0430\u0440\u0442\u0438\u043D\u043A\u0438, \u0430 \u043D\u0435 \u0441\u043A\u0440\u0438\u043D\u0448\u043E\u0442 \u0432\u0441\u0435\u0439 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B. \u041D\u0430 \u0441\u043A\u0430\u043D\u0430\u0445 (\u0433\u0434\u0435 \u0442\u0435\u043A\u0441\u0442 \u0438\u0437\u0432\u043B\u0435\u0447\u044C \u043D\u0435\u043B\u044C\u0437\u044F) \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0446\u0435\u043B\u0438\u043A\u043E\u043C. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0443 \u0437\u0430\u043D\u043E\u0432\u043E, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C.": "Off by default: when a page yields text, only the clean text is shown. Turn this on to also show the book's illustrations, diagrams and charts above the text \u2014 the pictures themselves are cropped out, not a screenshot of the whole page. Scanned pages (where no text can be extracted) are still shown in full. Reopen the book to apply.", "\u041F\u0435\u0440\u0435\u0432\u043E\u0434": "Translation", "\u041F\u0435\u0440\u0435\u0432\u043E\u0434 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u043D\u043E\u0433\u043E": "Translating a selection", "\u041E\u0440\u0438\u0433\u0438\u043D\u0430\u043B": "Original", "\u041F\u0435\u0440\u0435\u0432\u043E\u0434\u0438\u043C\u2026": "Translating\u2026", "\u041F\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438": "Translate", "\u041A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u043F\u0435\u0440\u0435\u0432\u043E\u0434": "Copy translation", "\u0412 \u0437\u0430\u043C\u0435\u0442\u043A\u0443": "To a note", "\u041F\u0443\u0441\u0442\u043E\u0439 \u043E\u0442\u0432\u0435\u0442 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0447\u0438\u043A\u0430": "The translator returned nothing", "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0435\u0440\u0435\u0432\u0435\u0441\u0442\u0438. \u041D\u0443\u0436\u0435\u043D \u0438\u043D\u0442\u0435\u0440\u043D\u0435\u0442 \u2014 \u043F\u0435\u0440\u0435\u0432\u043E\u0434 \u0438\u0434\u0451\u0442 \u0447\u0435\u0440\u0435\u0437 Google Translate, \u0438 \u0443 \u043D\u0435\u0433\u043E \u0435\u0441\u0442\u044C \u043B\u0438\u043C\u0438\u0442\u044B \u043D\u0430 \u0447\u0430\u0441\u0442\u044B\u0435 \u0437\u0430\u043F\u0440\u043E\u0441\u044B.": "Could not translate. An internet connection is required \u2014 translation goes through Google Translate, which rate-limits frequent requests.", "\u041A\u043D\u043E\u043F\u043A\u0430 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0430 \u0432 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0438": "Translate button in the selection popup", "\u0414\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u043A\u043D\u043E\u043F\u043A\u0443 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0430 \u0432 \u043F\u0430\u043D\u0435\u043B\u044C\u043A\u0443, \u043A\u043E\u0442\u043E\u0440\u0430\u044F \u043F\u043E\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0438 \u0442\u0435\u043A\u0441\u0442\u0430. \u041F\u0435\u0440\u0435\u0432\u043E\u0434 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0440\u044F\u0434\u043E\u043C \u0441 \u043E\u0440\u0438\u0433\u0438\u043D\u0430\u043B\u043E\u043C, \u0435\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0441\u043A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0438\u043B\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043F\u043E\u0434 \u0446\u0438\u0442\u0430\u0442\u043E\u0439. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0443 \u0437\u0430\u043D\u043E\u0432\u043E, \u0447\u0442\u043E\u0431\u044B \u043A\u043D\u043E\u043F\u043A\u0430 \u043F\u043E\u044F\u0432\u0438\u043B\u0430\u0441\u044C.": "Adds a translate button to the popup that appears when you select text. The translation is shown next to the original; you can copy it or save it into a note under the quote. Reopen the book for the button to appear.", "\u042D\u0442\u043E \u043F\u0435\u0440\u0432\u0430\u044F \u0432\u0435\u0440\u0441\u0438\u044F \u0444\u0443\u043D\u043A\u0446\u0438\u0438. \u041F\u0435\u0440\u0435\u0432\u043E\u0434 \u0438\u0434\u0451\u0442 \u0447\u0435\u0440\u0435\u0437 \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u044B\u0439 Google Translate: \u043D\u0443\u0436\u0435\u043D \u0438\u043D\u0442\u0435\u0440\u043D\u0435\u0442, \u0435\u0441\u0442\u044C \u043B\u0438\u043C\u0438\u0442\u044B \u043D\u0430 \u0447\u0430\u0441\u0442\u044B\u0435 \u0437\u0430\u043F\u0440\u043E\u0441\u044B, \u0430 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u043D\u044B\u0439 \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442 \u0443\u0445\u043E\u0434\u0438\u0442 \u043D\u0430 \u0441\u0435\u0440\u0432\u0435\u0440\u044B Google. \u0414\u043B\u044F \u0431\u043E\u043B\u044C\u0448\u0438\u0445 \u043E\u0431\u044A\u0451\u043C\u043E\u0432 \u043F\u043E\u043A\u0430 \u043D\u0435 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u043D\u043E.": "This is an early version of the feature. Translation uses the free Google Translate: it needs internet, is rate-limited, and the selected fragment is sent to Google's servers. Not intended for large volumes yet.", "\u041F\u0435\u0440\u0435\u0432\u043E\u0434\u0438\u0442\u044C \u043D\u0430 \u044F\u0437\u044B\u043A": "Translate into", "\u042F\u0437\u044B\u043A, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0438\u0442\u044C \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u043D\u044B\u0439 \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442. \u0418\u0441\u0445\u043E\u0434\u043D\u044B\u0439 \u044F\u0437\u044B\u043A \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.": "The language to translate the selected fragment into. The source language is detected automatically.", "\u0420\u0443\u0441\u0441\u043A\u0438\u0439": "Russian", "\u041F\u0435\u0440\u0435\u0432\u043E\u0434 \u2014 \u044D\u0442\u043E \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0439 \u0441\u0435\u0442\u0435\u0432\u043E\u0439 \u0437\u0430\u043F\u0440\u043E\u0441 \u043A Google. \u0415\u0441\u043B\u0438 \u0432\u0430\u043C \u0432\u0430\u0436\u043D\u043E, \u0447\u0442\u043E\u0431\u044B \u0442\u0435\u043A\u0441\u0442 \u043A\u043D\u0438\u0433\u0438 \u043D\u0438\u043A\u0443\u0434\u0430 \u043D\u0435 \u0443\u0445\u043E\u0434\u0438\u043B, \u043E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0444\u0443\u043D\u043A\u0446\u0438\u044E \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043D\u043E\u0439: \u0432\u0441\u0451 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u043E\u0435 \u0432 \u0447\u0438\u0442\u0430\u043B\u043A\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u043F\u043E\u043B\u043D\u043E\u0441\u0442\u044C\u044E \u043E\u0444\u043B\u0430\u0439\u043D.": "Translation is a separate network request to Google. If you need the book's text to stay on your device, leave this off: everything else in the reader works fully offline.", "\n\n**\u041F\u0435\u0440\u0435\u0432\u043E\u0434:**\n{0}": "\n\n**Translation:**\n{0}", "\u0427\u0438\u0442\u0430\u043B\u043A\u0430 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0442\u0440\u0438 \u0444\u043E\u0440\u043C\u0430\u0442\u0430: EPUB (.epub), FB2 (.fb2) \u0438 PDF (.pdf).": "The reader opens three formats: EPUB (.epub), FB2 (.fb2) and PDF (.pdf).", "1. \u041A\u043B\u0430\u0434\u0451\u0442\u0435 \u0444\u0430\u0439\u043B \u043A\u043D\u0438\u0433\u0438 (.epub, .fb2 \u0438\u043B\u0438 .pdf) \u0432 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 \u0438 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0435 \u0435\u0433\u043E \u043A\u043B\u0438\u043A\u043E\u043C.": "1. Put the book file (.epub, .fb2 or .pdf) in your vault and open it with a click.", "\u042D\u0442\u043E\u0442 FB2 \u0443\u043F\u0430\u043A\u043E\u0432\u0430\u043D \u0432 ZIP. \u0420\u0430\u0441\u043F\u0430\u043A\u0443\u0439\u0442\u0435 \u0430\u0440\u0445\u0438\u0432 \u0438 \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u0435 \u0432 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 \u0441\u0430\u043C \u0444\u0430\u0439\u043B .fb2.": "This FB2 is packed in a ZIP. Unpack the archive and put the .fb2 file itself into your vault.", "\u0412\u044B\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u043D\u0438\u0435 \u0442\u0435\u043A\u0441\u0442\u0430": "Text alignment", "\u0421\u043B\u0435\u0432\u0430": "Left", "\u041F\u043E \u0448\u0438\u0440\u0438\u043D\u0435": "Justify", "\u041F\u043E \u0446\u0435\u043D\u0442\u0440\u0443": "Center", "\u0421\u043F\u0440\u0430\u0432\u0430": "Right", "{0} \u0447 {1} \u043C\u0438\u043D": "{0} h {1} min", "{0} \u043C\u0438\u043D": "{0} min", "\u0421\u0432\u043E\u044F \u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u043D\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u043A\u043D\u0438\u0433\u0443": "A separate note per book", "\u041F\u0440\u0438 \u043F\u0435\u0440\u0432\u043E\u043C \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438 \u043A\u043D\u0438\u0433\u0438 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0441\u043E\u0437\u0434\u0430\u0451\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u0430\u044F \u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u0441 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435\u043C \u043A\u043D\u0438\u0433\u0438 (\u0432 \xAB\u041F\u0430\u043F\u043A\u0435 \u0437\u0430\u043C\u0435\u0442\u043E\u043A-\u043A\u043D\u0438\u0433\xBB, \u0438\u043D\u0430\u0447\u0435 \u0432 \xAB\u041F\u0430\u043F\u043A\u0435 \u0434\u043B\u044F \u043D\u043E\u0432\u044B\u0445 \u0437\u0430\u043C\u0435\u0442\u043E\u043A\xBB) \u0438 \u043F\u0440\u0438\u0432\u044F\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043A \u043D\u0435\u0439. \u0414\u0430\u043B\u044C\u0448\u0435 \u0432\u0441\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0438\u0437 \u044D\u0442\u043E\u0439 \u043A\u043D\u0438\u0433\u0438 \u0438\u0434\u0443\u0442 \u0432 \u0435\u0451 \u0437\u0430\u043C\u0435\u0442\u043A\u0443. \u0412\u044B\u043A\u043B\u044E\u0447\u0435\u043D\u043E \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E.": `On a book's first open, a dedicated note titled after the book is created (in the "Book notes folder", otherwise the "New notes folder") and linked to it. From then on every highlight from this book goes into its note. Off by default.`, "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u043A\u043D\u0438\u0433\u0438 \u0441\u043E\u0437\u0434\u0430\u043D\u0430: {0}": "Book note created: {0}", "\u042D\u0442\u043E \u043F\u0435\u0440\u0432\u0430\u044F \u0432\u0435\u0440\u0441\u0438\u044F \u0444\u0443\u043D\u043A\u0446\u0438\u0438 \u2014 \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u043D\u0430 \u043F\u0430\u0440\u0435 \u043A\u043D\u0438\u0433. \u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u0441\u043E\u0437\u0434\u0430\u0451\u0442\u0441\u044F \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u043F\u0440\u0438 \u043F\u0435\u0440\u0432\u043E\u043C \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438 \u043A\u043D\u0438\u0433\u0438.": "This is an early version of the feature \u2014 check the result on a couple of books first. The note is created once, on a book's first open.", "\u041A\u0430\u043A \u0432\u044B\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0442\u0435\u043A\u0441\u0442 \u0432 \u043A\u043E\u043B\u043E\u043D\u043A\u0435 \u0447\u0442\u0435\u043D\u0438\u044F. \u041C\u043E\u0436\u043D\u043E \u043C\u0435\u043D\u044F\u0442\u044C \u0438 \u043D\u0430 \u043B\u0435\u0442\u0443 \u2014 \u0432 \u043F\u0430\u043D\u0435\u043B\u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043A \u0447\u0442\u0435\u043D\u0438\u044F (\u0438\u043A\u043E\u043D\u043A\u0430 \u043F\u043E\u043B\u0437\u0443\u043D\u043A\u043E\u0432) \u0432 \u0441\u0430\u043C\u043E\u0439 \u043A\u043D\u0438\u0433\u0435. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0443 \u0437\u0430\u043D\u043E\u0432\u043E, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C.": "How text is aligned in the reading column. You can also change it on the fly from the reading-settings panel (sliders icon) inside a book. Reopen the book to apply.", "\u0421\u0435\u0433\u043E\u0434\u043D\u044F \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u043D\u043E: {0} \u043C\u0438\u043D. \u0412\u0441\u0435\u0433\u043E \u0437\u0430 \u0432\u0441\u0451 \u0432\u0440\u0435\u043C\u044F: {1}. \u041A\u043D\u043E\u043F\u043A\u0430 \u25B6 \u0432\u0432\u0435\u0440\u0445\u0443 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439 \u043E\u0442\u0441\u0447\u0451\u0442 \u0434\u043E \u0446\u0435\u043B\u0438 (\u043F\u0430\u0443\u0437\u0430 \u2014 \u23F8).": "Read today: {0} min. All-time total: {1}. The \u25B6 button at the top starts the countdown toward the goal (pause \u2014 \u23F8).", "\u0421\u0435\u0433\u043E\u0434\u043D\u044F \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u043D\u043E: {0} \u043C\u0438\u043D. \u0412\u0441\u0435\u0433\u043E \u0437\u0430 \u0432\u0441\u0451 \u0432\u0440\u0435\u043C\u044F: {1} \u043C\u0438\u043D.": "Read today: {0} min. All-time total: {1} min.", "\u0416\u0451\u043B\u0442\u044B\u0439": "Yellow", "\u0417\u0435\u043B\u0451\u043D\u044B\u0439": "Green", "\u0413\u043E\u043B\u0443\u0431\u043E\u0439": "Blue", "\u0420\u043E\u0437\u043E\u0432\u044B\u0439": "Pink", "\u0426\u0435\u043B\u044C \u0447\u0442\u0435\u043D\u0438\u044F \u043D\u0430 \u0441\u0435\u0433\u043E\u0434\u043D\u044F \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0442\u0430 \u{1F389}": "Today's reading goal reached \u{1F389}", "\u0422\u0430\u0439\u043C\u0435\u0440 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D \u2014 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u0435\u0433\u043E \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0447\u0442\u0435\u043D\u0438\u044F": "Timer is off \u2014 enable it in reading settings", "\u0422\u0430\u0439\u043C\u0435\u0440 \u0441\u0431\u0440\u043E\u0448\u0435\u043D": "Timer reset", "\u041B\u0438\u0441\u0442\u0430\u043D\u0438\u0435": "Page turning", "\u041A\u043D\u043E\u043F\u043A\u0430\u043C\u0438": "Buttons", "\u041F\u043E \u043A\u043B\u0438\u043A\u0443": "By click", "\xAB\u041F\u043E \u043A\u043B\u0438\u043A\u0443\xBB: \u043A\u043B\u0438\u043A \u043F\u043E \u043B\u0435\u0432\u043E\u0439 \u0447\u0430\u0441\u0442\u0438 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u2014 \u043D\u0430\u0437\u0430\u0434, \u043F\u043E \u043F\u0440\u0430\u0432\u043E\u0439 \u2014 \u0432\u043F\u0435\u0440\u0451\u0434. \u0426\u0435\u043D\u0442\u0440 \u0441\u0432\u043E\u0431\u043E\u0434\u0435\u043D \u0434\u043B\u044F \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0442\u0435\u043A\u0441\u0442\u0430.": '"By click": clicking the left part of the page goes back, the right part goes forward. The center stays free for selecting text.', "\u0412\u043A\u043B": "On", "\u0412\u044B\u043A\u043B": "Off", "\u0422\u0430\u043F \u043F\u043E \u043A\u0430\u0440\u0442\u0438\u043D\u043A\u0435 \u2014 \u0443\u0432\u0435\u043B\u0438\u0447\u0438\u0442\u044C \xB7 \u0444\u043E\u043D \u0438\u043B\u0438 \u2715 \u2014 \u0437\u0430\u043A\u0440\u044B\u0442\u044C": "Tap the image to zoom \xB7 background or \u2715 to close", "Elton Reader: \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u043C pdf.worker.js \u0438\u0437 CDN (\u043D\u0443\u0436\u0435\u043D \u0438\u043D\u0442\u0435\u0440\u043D\u0435\u0442). \u041F\u0440\u0438\u0447\u0438\u043D\u0430:": "Elton Reader: using pdf.worker.js from the CDN (internet required). Reason:", "Elton Reader: could not register .pdf, use right-click \u2192 \u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0432 Elton Reader": "Elton Reader: could not register .pdf, use right-click \u2192 Open in Elton Reader", "Book Reader \u2014 \u0411\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430": "Book Reader \u2014 Library", "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443": "Open library", "\u041E\u0442\u043A\u0440\u044B\u0442\u044C PDF \u0432 Book Reader": "Open PDF in Book Reader", "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u0447\u0442\u0435\u043D\u0438\u044F": "Save reading position", "\u042D\u043A\u0441\u043F\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "Export highlights to notes", "\u{1F4D6} \u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0432 Book Reader": "\u{1F4D6} Open in Book Reader", "\u041F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u043F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0435 (\u043E\u043D\u0431\u043E\u0440\u0434\u0438\u043D\u0433)": "Show welcome (onboarding)", "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u043A\u043D\u0438\u0433\u0438 \u0434\u043B\u044F \u0441\u0441\u044B\u043B\u043E\u043A \u2014 \u043D\u0430\u0447\u043D\u0438\u0442\u0435 \u0432\u0432\u043E\u0434\u0438\u0442\u044C \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435\u2026": "Book note for links \u2014 start typing a name\u2026", "\u0428\u0430\u0431\u043B\u043E\u043D \u0437\u0430\u043C\u0435\u0442\u043A\u0438 \u2014 \u043D\u0430\u0447\u043D\u0438\u0442\u0435 \u0432\u0432\u043E\u0434\u0438\u0442\u044C \u043F\u0443\u0442\u044C\u2026": "Note template \u2014 start typing a path\u2026", "## \u0417\u0430\u043C\u0435\u0442\u043A\u0438 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439": "## Notes from highlights", "\u0417\u0430\u043C\u0435\u0442\u043A\u0430": "Note", "\u041F\u0443\u0441\u0442\u043E\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435": "Empty highlight", "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u0441\u043E\u0437\u0434\u0430\u043D\u0430": "Note created", "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0441\u043E\u0437\u0434\u0430\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443": "Could not create the note", "\u041D\u0435\u0442 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439 \u0434\u043B\u044F \u044D\u043A\u0441\u043F\u043E\u0440\u0442\u0430": "No highlights to export", "\u041A\u043D\u0438\u0433\u0430": "Book", "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u044D\u043A\u0441\u043F\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F": "Could not export highlights", "\u041D\u0435\u0442": "No", "\u0414\u0430": "Yes", "\u0414\u043B\u044F \u043A\u043D\u0438\u0433\u0438 \u043D\u0435 \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u043D\u0430 \u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u2014 \u0437\u0430\u0434\u0430\u0439\u0442\u0435 \u0435\u0451 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445": "No note is linked to this book \u2014 set it in settings", "## \u0426\u0438\u0442\u0430\u0442\u044B": "## Quotes", "\u0426\u0438\u0442\u0430\u0442\u044B \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u044B": "Quotes added", "\u0414\u0430, \u043E\u0442\u043A\u0440\u044B\u0442\u044C": "Yes, open", "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0446\u0438\u0442\u0430\u0442\u044B \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438": "Could not add quotes to the book note", "\u041A\u0430\u043A \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C\u0441\u044F Book Reader": "How to use Book Reader", "\u0427\u0442\u043E \u0434\u0435\u043B\u0430\u0435\u0442 \u043A\u0430\u0436\u0434\u0430\u044F \u043A\u043D\u043E\u043F\u043A\u0430 \u0438 \u0437\u0430\u0447\u0435\u043C": "What each button does and why", "\u0412\u0435\u0440\u0445\u043D\u044F\u044F \u043F\u0430\u043D\u0435\u043B\u044C": "Top bar", "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u043F\u043E\u0437\u0438\u0446\u0438\u044E": "Save position", "\u0417\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442, \u0433\u0434\u0435 \u0432\u044B \u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u0438\u0441\u044C, \u0438 \u0441\u0442\u0430\u0432\u0438\u0442 \u0442\u043E\u0447\u043A\u0443 \u0432\u043E\u0437\u0432\u0440\u0430\u0442\u0430 (\u043F\u043E\u043C\u0435\u0447\u0435\u043D\u0430 \u{1F4BE} \u0432 \xAB\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u2192 \u0412\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u043C\u0435\u0441\u0442\u0443\xBB). \u042D\u0442\u043E \u043A\u0430\u043A \xAB\u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435\xBB \u0432 \u0438\u0433\u0440\u0435 \u2014 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u043F\u0435\u0440\u0435\u0434 \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u0435\u043C \u043A\u043D\u0438\u0433\u0438, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u0431\u044B\u0442\u044C \u0442\u043E\u0447\u043D\u043E \u0443\u0432\u0435\u0440\u0435\u043D\u044B, \u0447\u0442\u043E \u043C\u0435\u0441\u0442\u043E \u043D\u0435 \u043F\u043E\u0442\u0435\u0440\u044F\u0435\u0442\u0441\u044F.": `Remembers where you left off and drops a restore point (marked \u{1F4BE} in "Settings \u2192 Jump back"). It's like a "save" in a game \u2014 press it before closing the book if you want to be completely sure your spot won't be lost.`, "\u041E\u0431\u043D\u043E\u0432\u0438\u0442\u044C": "Refresh", "\u041F\u0435\u0440\u0435\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 \u0437\u0430\u043D\u043E\u0432\u043E, \u0435\u0441\u043B\u0438 \u0432\u0451\u0440\u0441\u0442\u043A\u0430 \xAB\u043F\u043E\u0435\u0445\u0430\u043B\u0430\xBB \u2014 \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u043E\u0441\u043B\u0435 \u0441\u043C\u0435\u043D\u044B \u0440\u0430\u0437\u043C\u0435\u0440\u0430 \u043E\u043A\u043D\u0430 \u0438\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u044F/\u0437\u0430\u043A\u0440\u044B\u0442\u0438\u044F \u0431\u043E\u043A\u043E\u0432\u043E\u0439 \u043F\u0430\u043D\u0435\u043B\u0438 \u0438\u043B\u0438 \u0432\u043A\u043B\u0430\u0434\u043A\u0438 (\u0442\u0435\u043A\u0441\u0442 \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u043E\u0431\u0440\u0430\u0437\u0438\u0442\u044C\u0441\u044F \u043A\u0440\u0438\u0432\u043E). \u0422\u0435\u043A\u0443\u0449\u0443\u044E \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u043F\u0440\u0438 \u044D\u0442\u043E\u043C \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442.": "Rebuilds the page if the layout breaks \u2014 for example, after resizing the window or opening/closing a sidebar panel or tab (the text may look misaligned). Your current position is preserved.", "\u0412\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F": "Highlights", "\u041E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u043F\u0438\u0441\u043E\u043A \u0432\u0441\u0435\u0445 \u0432\u0430\u0448\u0438\u0445 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439 \u0432 \u044D\u0442\u043E\u0439 \u043A\u043D\u0438\u0433\u0435. \u041A\u043B\u0438\u043A \u043F\u043E \u0441\u0442\u0440\u043E\u043A\u0435 \u2014 \u043F\u0435\u0440\u0435\u0445\u043E\u0434 \u043A \u044D\u0442\u043E\u043C\u0443 \u043C\u0435\u0441\u0442\u0443. \u0421\u0432\u0435\u0440\u0445\u0443 \u0441\u043F\u0438\u0441\u043A\u0430 \u2014 \u043A\u043D\u043E\u043F\u043A\u0430 \u044D\u043A\u0441\u043F\u043E\u0440\u0442\u0430 \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0438.": "Opens the list of all your highlights in this book. Click a row to jump to that spot. Above the list is the export-to-notes button.", "\u0421\u043E\u0434\u0435\u0440\u0436\u0430\u043D\u0438\u0435": "Contents", "\u041E\u0433\u043B\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043A\u043D\u0438\u0433\u0438 \u2014 \u0431\u044B\u0441\u0442\u0440\u044B\u0439 \u043F\u0435\u0440\u0435\u0445\u043E\u0434 \u043F\u043E \u0433\u043B\u0430\u0432\u0430\u043C.": "The book's table of contents \u2014 quickly jump between chapters.", "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438": "Settings", "\u0422\u0435\u043C\u0430, \u0448\u0440\u0438\u0444\u0442, \u0440\u0430\u0437\u043C\u0435\u0440 \u0442\u0435\u043A\u0441\u0442\u0430, \u0447\u0438\u0441\u043B\u043E \u043A\u043E\u043B\u043E\u043D\u043E\u043A \u0438 \u0431\u043B\u043E\u043A \xAB\u0412\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u043C\u0435\u0441\u0442\u0443\xBB \u2014 \u0441\u043F\u0438\u0441\u043E\u043A \u0442\u043E\u0447\u0435\u043A, \u043A \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u0430\u0442\u0438\u0442\u044C\u0441\u044F.": 'Theme, font, text size, column count and the "Jump back" block \u2014 a list of points you can roll back to.', "\u0421\u043F\u0440\u0430\u0432\u043A\u0430": "Help", "\u042D\u0442\u043E \u043E\u043A\u043D\u043E.": "This window.", "\u0427\u0442\u0435\u043D\u0438\u0435 \u0438 \u043D\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u044F": "Reading and navigation", "\u041B\u0438\u0441\u0442\u0430\u0442\u044C \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B": "Turn pages", "\u0421\u0442\u0440\u0435\u043B\u043A\u0438 \u0432\u043D\u0438\u0437\u0443 \u044D\u043A\u0440\u0430\u043D\u0430, \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u2190 \u2192 \u2191 \u2193 \u0438 \u043F\u0440\u043E\u0431\u0435\u043B, \u043B\u0438\u0431\u043E \u0441\u0432\u0430\u0439\u043F \u043F\u0430\u043B\u044C\u0446\u0435\u043C \u043D\u0430 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u0435. \u041A\u0430\u0436\u0434\u043E\u0435 \u043F\u0435\u0440\u0435\u043B\u0438\u0441\u0442\u044B\u0432\u0430\u043D\u0438\u0435 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u043E\u0437\u0438\u0446\u0438\u044E \u2014 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u0436\u0430\u0442\u044C \xAB\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C\xBB \u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E.": `The arrows at the bottom of the screen, the \u2190 \u2192 \u2191 \u2193 keys and space, or a finger swipe on mobile. Every page turn saves your position automatically \u2014 you don't need to press "Save" separately.`, "\u0412\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0438 \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "Highlights and notes", "\u0412\u044B\u0434\u0435\u043B\u0438\u0442\u044C \u0442\u0435\u043A\u0441\u0442": "Highlight text", "\u0412\u044B\u0434\u0435\u043B\u0438\u0442\u0435 \u0444\u0440\u0430\u0433\u043C\u0435\u043D\u0442 \u043C\u044B\u0448\u044C\u044E \u0438\u043B\u0438 \u043F\u0430\u043B\u044C\u0446\u0435\u043C \u2014 \u0432\u0441\u043F\u043B\u044B\u0432\u0451\u0442 \u043F\u0430\u043B\u0438\u0442\u0440\u0430 \u0446\u0432\u0435\u0442\u043E\u0432. \u041A\u043B\u0438\u043A \u043F\u043E \u0443\u0436\u0435 \u0433\u043E\u0442\u043E\u0432\u043E\u043C\u0443 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044E \u2014 \u0441\u043C\u0435\u043D\u0438\u0442\u044C \u0446\u0432\u0435\u0442 \u0438\u043B\u0438 \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u0435\u0433\u043E.": "Select a fragment with the mouse or a finger \u2014 a color palette pops up. Click an existing highlight to change its color or remove it.", "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F": "Create a note from a highlight", "\u041F\u0440\u0430\u0432\u044B\u0439 \u043A\u043B\u0438\u043A \u043F\u043E \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u043D\u043E\u043C\u0443 \u0442\u0435\u043A\u0441\u0442\u0443 \u2192 \xAB\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u043D\u043E\u0432\u0443\u044E \u0437\u0430\u043C\u0435\u0442\u043A\u0443\xBB. \u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u0441\u043E\u0437\u0434\u0430\u0451\u0442\u0441\u044F \u043F\u043E \u0432\u0430\u0448\u0435\u043C\u0443 \u0448\u0430\u0431\u043B\u043E\u043D\u0443 \u0432 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u043F\u0430\u043F\u043A\u0435, \u0441 \u0446\u0438\u0442\u0430\u0442\u043E\u0439 \u0438 \u0441\u0441\u044B\u043B\u043A\u043E\u0439 \u043D\u0430 \u043A\u043D\u0438\u0433\u0443.": 'Right-click the highlighted text \u2192 "Create new note". The note is created from your template in the chosen folder, with the quote and a link to the book.', "\u042D\u043A\u0441\u043F\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0432\u0441\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F": "Export all highlights", "\u041A\u043D\u043E\u043F\u043A\u0430 \u0432\u0432\u0435\u0440\u0445\u0443 \u043F\u0430\u043D\u0435\u043B\u0438 \xAB\u0412\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F\xBB. \u0421\u043E\u0431\u0438\u0440\u0430\u0435\u0442 \u0432\u0441\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u043A\u043D\u0438\u0433\u0438 \u0440\u0430\u0437\u043E\u043C. \u0421\u043F\u0440\u043E\u0441\u0438\u0442 \u0444\u043E\u0440\u043C\u0430\u0442: \u043E\u0434\u043D\u0430 \u043E\u0431\u0449\u0430\u044F \u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u0441\u043E \u0432\u0441\u0435\u043C\u0438 \u0446\u0438\u0442\u0430\u0442\u0430\u043C\u0438, \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0439 \u0444\u0430\u0439\u043B \u043D\u0430 \u043A\u0430\u0436\u0434\u043E\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435, \u043B\u0438\u0431\u043E \u0432\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0432\u0441\u0435 \u0446\u0438\u0442\u0430\u0442\u044B \u0442\u0435\u043A\u0441\u0442\u043E\u043C \u043F\u0440\u044F\u043C\u043E \u0432 \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u043D\u043D\u0443\u044E \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438.": `The button at the top of the "Highlights" panel. Collects all of the book's highlights at once. It asks for a format: one shared note with all quotes, a separate file per highlight, or inserting all quotes as text straight into the linked book note.`, "\u041A\u0443\u0434\u0430 \u0432\u0435\u0441\u0442\u0438 \u0441\u0441\u044B\u043B\u043A\u0443 \xAB\u2014 \u0438\u0437 [[\u2026]]\xBB \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0430\u0445 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439. \u041F\u0443\u0441\u0442\u043E \u2014 \u0438\u043C\u044F \u0444\u0430\u0439\u043B\u0430 \u043A\u043D\u0438\u0433\u0438.": `Where the "\u2014 from [[\u2026]]" link in highlight notes points. Empty \u2014 the book's file name.`, "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0443\u2026": "Open a book first\u2026", "\u0412\u044B\u0431\u0440\u0430\u0442\u044C \u0438\u0437 \u0441\u043F\u0438\u0441\u043A\u0430\u2026": "Choose from the list\u2026", "\u0412 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 \u043D\u0435\u0442 \u0437\u0430\u043C\u0435\u0442\u043E\u043A": "No notes in the vault", "\u0421\u0432\u043E\u0439 \u0448\u0430\u0431\u043B\u043E\u043D \u0442\u043E\u043B\u044C\u043A\u043E \u0434\u043B\u044F \u044D\u0442\u043E\u0439 \u043A\u043D\u0438\u0433\u0438 (\u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u043F\u043E\u0434 \u0436\u0430\u043D\u0440). \u041F\u0443\u0441\u0442\u043E \u2014 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u043E\u0431\u0449\u0438\u0439 \u0448\u0430\u0431\u043B\u043E\u043D \u0438\u0437 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043A \u043F\u043B\u0430\u0433\u0438\u043D\u0430.": "A template just for this book (for example, per genre). Empty \u2014 the shared template from the plugin settings is used.", "Templates/\u0428\u0430\u0431\u043B\u043E\u043D.md": "Templates/Template.md", "\u041F\u0440\u043E \u0430\u0432\u0442\u043E\u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435": "About autosave", "\u041F\u043E\u0437\u0438\u0446\u0438\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u0441\u0430\u043C\u0430 \u043F\u0440\u0438 \u043A\u0430\u0436\u0434\u043E\u043C \u043F\u0435\u0440\u0435\u043B\u0438\u0441\u0442\u044B\u0432\u0430\u043D\u0438\u0438 \u0438 \u0445\u0440\u0430\u043D\u0438\u0442\u0441\u044F \u0432 \u043E\u0431\u0449\u0435\u043C \u0444\u0430\u0439\u043B\u0435, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0438\u0440\u0443\u0435\u0442\u0441\u044F \u043C\u0435\u0436\u0434\u0443 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430\u043C\u0438 (Obsidian Sync). \u041F\u0435\u0440\u0435\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B (\u0441\u043C\u0435\u043D\u0430 \u0440\u0430\u0437\u043C\u0435\u0440\u0430 \u043E\u043A\u043D\u0430, \u043F\u0430\u043D\u0435\u043B\u0435\u0439, \u043C\u0430\u0441\u0448\u0442\u0430\u0431\u0430) \u0431\u043E\u043B\u044C\u0448\u0435 \u041D\u0415 \u0434\u0432\u0438\u0433\u0430\u0435\u0442 \u0438 \u043D\u0435 \u043F\u0435\u0440\u0435\u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u2014 \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D \u043D\u0435 \xAB\u0443\u0435\u0437\u0436\u0430\u0435\u0442\xBB \u0441\u0430\u043C \u043F\u043E \u0441\u0435\u0431\u0435.": `Your position is saved automatically on every page turn and kept in a shared file that syncs across devices (Obsidian Sync). Rebuilding the page (resizing the window, panels, zoom) no longer moves or re-saves progress \u2014 so it won't "drift" on its own.`, "\u0414\u043E\u0431\u0440\u043E \u043F\u043E\u0436\u0430\u043B\u043E\u0432\u0430\u0442\u044C \u0432 Book Reader!": "Welcome to Book Reader!", "\u042D\u0442\u043E \u0443\u044E\u0442\u043D\u0430\u044F \u0447\u0438\u0442\u0430\u043B\u043A\u0430 \u043A\u043D\u0438\u0433 \u043F\u0440\u044F\u043C\u043E \u0432\u043D\u0443\u0442\u0440\u0438 Obsidian. \u0427\u0438\u0442\u0430\u0435\u0442\u0435, \u0432\u044B\u0434\u0435\u043B\u044F\u0435\u0442\u0435 \u0432\u0430\u0436\u043D\u043E\u0435 \u0438 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0438 \u2014 \u043D\u0435 \u0432\u044B\u0445\u043E\u0434\u044F \u0438\u0437 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0430.": "It's a cozy book reader right inside Obsidian. Read, highlight what matters and turn highlights into notes \u2014 without leaving your vault.", "\u041F\u0440\u043E\u043B\u0438\u0441\u0442\u0430\u0439\u0442\u0435 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u044D\u043A\u0440\u0430\u043D\u043E\u0432 \u0441\u0442\u0440\u0435\u043B\u043A\u043E\u0439 \u2192 (\u0438\u043B\u0438 \u043A\u043D\u043E\u043F\u043A\u043E\u0439 \xAB\u0414\u0430\u043B\u0435\u0435\xBB). \u042D\u0442\u043E \u0437\u0430\u0439\u043C\u0451\u0442 \u043C\u0438\u043D\u0443\u0442\u0443, \u0437\u0430\u0442\u043E \u043F\u043E\u0442\u043E\u043C \u0432\u0441\u0451 \u0431\u0443\u0434\u0435\u0442 \u043F\u043E\u043D\u044F\u0442\u043D\u043E.": 'Flip through a few screens with the \u2192 arrow (or the "Next" button). It takes a minute, but then everything will be clear.', "\u041A\u0430\u043A\u0438\u0435 \u0444\u043E\u0440\u043C\u0430\u0442\u044B \u0438 \u043A\u0430\u043A \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043A\u043D\u0438\u0433\u0443": "Which formats, and how to open a book", "\u0427\u0438\u0442\u0430\u043B\u043A\u0430 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0434\u0432\u0430 \u0444\u043E\u0440\u043C\u0430\u0442\u0430: EPUB (\u0444\u0430\u0439\u043B\u044B .epub) \u0438 PDF (\u0444\u0430\u0439\u043B\u044B .pdf).": "The reader opens two formats: EPUB (.epub files) and PDF (.pdf files).", "\u0427\u0442\u043E\u0431\u044B \u0447\u0438\u0442\u0430\u0442\u044C \u043A\u043D\u0438\u0433\u0443, \u043F\u043E\u043B\u043E\u0436\u0438\u0442\u0435 \u0435\u0451 \u0444\u0430\u0439\u043B \u0432 \u0441\u0432\u043E\u0451 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 Obsidian \u0438 \u043F\u0440\u043E\u0441\u0442\u043E \u043A\u043B\u0438\u043A\u043D\u0438\u0442\u0435 \u043F\u043E \u043D\u0435\u043C\u0443 \u2014 \u043E\u043D\u0430 \u043E\u0442\u043A\u0440\u043E\u0435\u0442\u0441\u044F \u0432 \u0447\u0438\u0442\u0430\u043B\u043A\u0435.": "To read a book, put its file into your Obsidian vault and just click it \u2014 it opens in the reader.", "\u041D\u0430 \u043B\u0435\u0432\u043E\u0439 \u043F\u0430\u043D\u0435\u043B\u0438 \u0435\u0441\u0442\u044C \u0437\u043D\u0430\u0447\u043E\u043A \u{1F4D6} \xAB\u0411\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430\xBB \u2014 \u0442\u0430\u043C \u0432\u0441\u0435 \u0432\u0430\u0448\u0438 \u043A\u043D\u0438\u0433\u0438 \u0441 \u043E\u0431\u043B\u043E\u0436\u043A\u0430\u043C\u0438 \u0432 \u043E\u0434\u043D\u043E\u043C \u043C\u0435\u0441\u0442\u0435.": `In the left sidebar there's a \u{1F4D6} "Library" icon \u2014 all your books with covers in one place.`, "\u042D\u0442\u043E \u0441\u0430\u043C\u0430\u044F \u043F\u0435\u0440\u0432\u0430\u044F \u0432\u0435\u0440\u0441\u0438\u044F": "This is the very first version", "\u041F\u043E\u0436\u0430\u043B\u0443\u0439\u0441\u0442\u0430, \u043D\u0435 \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0439\u0442\u0435 \u0441\u0440\u0430\u0437\u0443 \u043C\u043D\u043E\u0433\u043E \u043A\u043D\u0438\u0433. \u041D\u0430\u0447\u043D\u0438\u0442\u0435 \u0441 \u0434\u0432\u0443\u0445-\u0442\u0440\u0451\u0445 \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435, \u0447\u0442\u043E \u0432\u0441\u0451 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0441\u0442\u0430\u0431\u0438\u043B\u044C\u043D\u043E \u0438\u043C\u0435\u043D\u043D\u043E \u043D\u0430 \u0432\u0430\u0448\u0435\u043C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435.": "Please don't load a lot of books at once. Start with two or three and check that everything works reliably on your device.", "\u041E\u0441\u043E\u0431\u0435\u043D\u043D\u043E \u0430\u043A\u043A\u0443\u0440\u0430\u0442\u043D\u043E \u0441 \u043E\u0447\u0435\u043D\u044C \u0431\u043E\u043B\u044C\u0448\u0438\u043C\u0438 PDF (\u0441\u043E\u0442\u043D\u0438 \u0441\u0442\u0440\u0430\u043D\u0438\u0446 \u0438\u043B\u0438 \u0441\u043A\u0430\u043D\u044B \u043A\u0430\u0440\u0442\u0438\u043D\u043E\u043A) \u2014 \u043E\u043D\u0438 \u0442\u044F\u0436\u0451\u043B\u044B\u0435 \u0438 \u043C\u043E\u0433\u0443\u0442 \u043F\u043E\u0434\u0442\u043E\u0440\u043C\u0430\u0436\u0438\u0432\u0430\u0442\u044C.": "Be especially careful with very large PDFs (hundreds of pages or scanned images) \u2014 they're heavy and may lag.", "\u041F\u043B\u0430\u0433\u0438\u043D \u0431\u0443\u0434\u0435\u0442 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C\u0441\u044F \u043B\u0443\u0447\u0448\u0435. \u0410 \u043F\u043E\u043A\u0430 \u2014 \u043F\u043E \u0447\u0443\u0442\u044C-\u0447\u0443\u0442\u044C \u0438 \u0431\u0435\u0440\u0435\u0436\u043D\u043E \u{1F642}": "The plugin will keep getting better. For now \u2014 little by little and gently \u{1F642}", "\u0412\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F: \u0446\u0432\u0435\u0442\u0430 \u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F": "Highlights: colors and actions", "\u0412\u044B\u0434\u0435\u043B\u0438\u0442\u0435 \u0442\u0435\u043A\u0441\u0442 \u043F\u0430\u043B\u044C\u0446\u0435\u043C \u0438\u043B\u0438 \u043C\u044B\u0448\u044C\u044E \u2014 \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u043F\u0430\u043B\u0438\u0442\u0440\u0430. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0446\u0432\u0435\u0442, \u0438 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u0441\u044F.": "Select text with a finger or the mouse \u2014 a palette appears. Pick a color and the highlight is saved.", "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u043D\u0430 \u0443\u0436\u0435 \u0433\u043E\u0442\u043E\u0432\u043E\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u2014 \u043E\u0442\u043A\u0440\u043E\u0435\u0442\u0441\u044F \u0442\u043E \u0436\u0435 \u043C\u0435\u043D\u044E: \u0441\u043C\u0435\u043D\u0438\u0442\u044C \u0446\u0432\u0435\u0442, \u0441\u043A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u0442\u044C, \u043F\u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0437\u0430\u043A\u043B\u0430\u0434\u043A\u0443 \xAB\u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u0441\u044F \u0437\u0434\u0435\u0441\u044C\xBB, \u0441\u043E\u0437\u0434\u0430\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443, \u043E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438 \u0438\u043B\u0438 \u0443\u0434\u0430\u043B\u0438\u0442\u044C.": 'Tap an existing highlight \u2014 the same menu opens: change color, copy, set a "stopped here" bookmark, create a note, send it to the book note, or delete.', "\u0412\u0441\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u043A\u043D\u0438\u0433\u0438 \u0441\u043E\u0431\u0440\u0430\u043D\u044B \u0432 \u043F\u0430\u043D\u0435\u043B\u0438 \u{1F58D}\uFE0F \u043D\u0430\u0432\u0435\u0440\u0445\u0443 \u2014 \u043E\u0442\u0442\u0443\u0434\u0430 \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u043B\u044E\u0431\u043E\u043C\u0443 \u0438\u043B\u0438 \u044D\u043A\u0441\u043F\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0432\u0441\u0435 \u0441\u0440\u0430\u0437\u0443.": "All of the book's highlights are gathered in the \u{1F58D}\uFE0F panel at the top \u2014 from there you can jump to any of them or export them all at once.", "\u0427\u0442\u043E \u0442\u0430\u043A\u043E\u0435 \xAB\u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u043A\u043D\u0438\u0433\u0438\xBB": 'What a "book note" is', "\u0423 \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u043D\u0438\u0433\u0438 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0432\u0435\u0441\u0442\u0438 \u043E\u0434\u043D\u0443 \u043E\u0431\u044B\u0447\u043D\u0443\u044E \u0437\u0430\u043C\u0435\u0442\u043A\u0443 Obsidian \u2014 \u0435\u0451 \xAB\u0433\u043B\u0430\u0432\u043D\u0443\u044E \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443\xBB, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \xAB\u041C\u0430\u0441\u0442\u0435\u0440 \u0438 \u041C\u0430\u0440\u0433\u0430\u0440\u0438\u0442\u0430.md\xBB.": 'For each book you can keep one ordinary Obsidian note \u2014 its "home page", for example "The Master and Margarita.md".', "\u041A\u043E\u0433\u0434\u0430 \u0432\u044B \u0441\u043E\u0437\u0434\u0430\u0451\u0442\u0435 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F, \u0432 \u043D\u0435\u0439 \u0441\u0442\u0430\u0432\u0438\u0442\u0441\u044F \u0441\u0441\u044B\u043B\u043A\u0430 \u043D\u0430 \u044D\u0442\u0443 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438. \u0410 \u0435\u0449\u0451 \u0446\u0438\u0442\u0430\u0442\u044B \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043F\u0440\u0430\u0432\u043B\u044F\u0442\u044C \u043F\u0440\u044F\u043C\u043E \u0432 \u043D\u0435\u0451 \u2014 \u0442\u0430\u043A \u0432\u0441\u0435 \u043C\u044B\u0441\u043B\u0438 \u043F\u043E \u043A\u043D\u0438\u0433\u0435 \u0441\u043E\u0431\u0438\u0440\u0430\u044E\u0442\u0441\u044F \u0432 \u043E\u0434\u043D\u043E\u043C \u043C\u0435\u0441\u0442\u0435.": "When you create a note from a highlight, it links back to this book note. You can also send quotes straight into it \u2014 so all your thoughts on the book gather in one place.", "\u042D\u0442\u043E \u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u043D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0442\u044C \u043F\u0440\u044F\u043C\u043E \u0441\u0435\u0439\u0447\u0430\u0441 \u2014 \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438 \u043C\u043E\u0436\u043D\u043E \u0432 \u043B\u044E\u0431\u043E\u0439 \u043C\u043E\u043C\u0435\u043D\u0442 \u043F\u043E\u0437\u0436\u0435. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0443, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u0437\u043D\u0430\u0447\u043E\u043A \u24D8 (\u0441\u043F\u0440\u0430\u0432\u043A\u0430) \u0432\u0432\u0435\u0440\u0445\u0443 \u0447\u0438\u0442\u0430\u043B\u043A\u0438 \u0438 \u0437\u0430\u043F\u043E\u043B\u043D\u0438\u0442\u0435 \u043F\u043E\u043B\u0435 \xAB\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u043A\u043D\u0438\u0433\u0438 \u0434\u043B\u044F \u0441\u0441\u044B\u043B\u043E\u043A\xBB. \u041F\u043E\u043A\u0430 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043F\u0440\u0438\u0432\u044F\u0437\u0430\u043D\u043E, \u0441\u0441\u044B\u043B\u043A\u0438 \u043F\u0440\u043E\u0441\u0442\u043E \u0432\u0435\u0434\u0443\u0442 \u043D\u0430 \u0438\u043C\u044F \u0444\u0430\u0439\u043B\u0430 \u043A\u043D\u0438\u0433\u0438.": `You don't have to set this up right now \u2014 you can link a book note at any time later. Open the book, press the \u24D8 (help) icon at the top of the reader and fill in the "Book note for links" field. Until something is linked, links simply point to the book's file name.`, "\u0413\u0434\u0435 \u0432\u0441\u0451 \u0445\u0440\u0430\u043D\u0438\u0442\u0441\u044F": "Where everything is stored", "\u0412\u0430\u0448 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u0447\u0442\u0435\u043D\u0438\u044F \u0438 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F \u0444\u0430\u0439\u043B\u0430\u043C\u0438 \u043F\u0440\u044F\u043C\u043E \u0432 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 (\u0440\u044F\u0434\u043E\u043C \u0441 \u043A\u043D\u0438\u0433\u0430\u043C\u0438 \u0438\u043B\u0438 \u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0439 \u043F\u0430\u043F\u043A\u0435 \u2014 \u044D\u0442\u043E \u043D\u0430\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044F). \u041D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0441\u043F\u0440\u044F\u0442\u0430\u043D\u043E \xAB\u0432\u043D\u0443\u0442\u0440\u0438 \u043F\u043B\u0430\u0433\u0438\u043D\u0430\xBB \u2014 \u0432\u0441\u0451 \u043B\u0435\u0436\u0438\u0442 \u0443 \u0432\u0430\u0441.": `Your reading progress and highlights are stored as files right in the vault (next to the books or in a separate folder \u2014 it's configurable). Nothing is hidden "inside the plugin" \u2014 it's all yours.`, "\u0417\u0430\u043C\u0435\u0442\u043A\u0438 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439 \u0438 \u0437\u0430\u043C\u0435\u0442\u043A\u0438 \u043A\u043D\u0438\u0433\u0438 \u2014 \u044D\u0442\u043E \u0441\u0430\u043C\u044B\u0435 \u043E\u0431\u044B\u0447\u043D\u044B\u0435 .md \u0437\u0430\u043C\u0435\u0442\u043A\u0438 \u0432 \u0432\u0430\u0448\u0435\u0439 \u043F\u0430\u043F\u043A\u0435. \u041E\u0442\u043A\u0440\u044B\u0432\u0430\u0439\u0442\u0435, \u0440\u0435\u0434\u0430\u043A\u0442\u0438\u0440\u0443\u0439\u0442\u0435 \u0438 \u0441\u0432\u044F\u0437\u044B\u0432\u0430\u0439\u0442\u0435 \u0438\u0445, \u043A\u0430\u043A \u043B\u044E\u0431\u044B\u0435 \u0434\u0440\u0443\u0433\u0438\u0435.": "Highlight notes and book notes are ordinary .md notes in your folder. Open, edit and link them like any others.", "\u041F\u0440\u043E \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u044E": "About syncing", "\u0420\u0430\u0437 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u0438 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u2014 \u044D\u0442\u043E \u0444\u0430\u0439\u043B\u044B \u0432 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435, \u043E\u043D\u0438 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0438\u0440\u0443\u044E\u0442\u0441\u044F \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u043D\u0438\u043C (Obsidian Sync, iCloud \u0438 \u0442.\u043F.).": "Since progress and highlights are files in the vault, they sync along with it (Obsidian Sync, iCloud, etc.).", "\u0414\u0430\u0439\u0442\u0435 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u0438 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u044C\u0441\u044F, \u043F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0442\u044C \u0442\u0443 \u0436\u0435 \u043A\u043D\u0438\u0433\u0443 \u043D\u0430 \u0434\u0440\u0443\u0433\u043E\u043C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435, \u0438 \u043D\u0435 \u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u043E\u0434\u043D\u0443 \u043A\u043D\u0438\u0433\u0443 \u043D\u0430 \u0434\u0432\u0443\u0445 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430\u0445 \u0441\u0440\u0430\u0437\u0443 \u2014 \u0438\u043D\u0430\u0447\u0435 \u043F\u043E\u0437\u0438\u0446\u0438\u044F \u043C\u043E\u0436\u0435\u0442 \xAB\u043F\u043E\u0441\u043F\u043E\u0440\u0438\u0442\u044C \u0441\u0430\u043C\u0430 \u0441 \u0441\u043E\u0431\u043E\u0439\xBB.": `Let syncing finish before opening the same book on another device, and don't read one book on two devices at once \u2014 otherwise the position may "argue with itself".`, "\u041D\u0430 \u0440\u0430\u0437\u043D\u044B\u0445 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430\u0445 \u043F\u0443\u0442\u044C \u043A \u043F\u0430\u043F\u043A\u0435 \u0441 \u043A\u043D\u0438\u0433\u0430\u043C\u0438 \u0431\u044B\u0432\u0430\u0435\u0442 \u0440\u0430\u0437\u043D\u044B\u043C \u2014 \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u043F\u0430\u043F\u043A\u0438 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u043F\u043B\u0430\u0433\u0438\u043D\u0430.": "The path to the books folder can differ across devices \u2014 check the folders in the plugin settings.", "\u041F\u0440\u0438\u043C\u0435\u0440: \u043A\u0430\u043A \u044D\u0442\u043E \u0432\u0441\u0451 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442": "Example: how it all works", "1. \u041A\u043B\u0430\u0434\u0451\u0442\u0435 \u0444\u0430\u0439\u043B \u043A\u043D\u0438\u0433\u0438 (.epub \u0438\u043B\u0438 .pdf) \u0432 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 \u0438 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0435 \u0435\u0433\u043E \u043A\u043B\u0438\u043A\u043E\u043C.": "1. Put a book file (.epub or .pdf) into the vault and open it with a click.", "2. \u0427\u0438\u0442\u0430\u0435\u0442\u0435. \u041F\u043E\u0437\u0438\u0446\u0438\u044F \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u0441\u0430\u043C\u0430 \u043F\u0440\u0438 \u043A\u0430\u0436\u0434\u043E\u043C \u043F\u0435\u0440\u0435\u043B\u0438\u0441\u0442\u044B\u0432\u0430\u043D\u0438\u0438 \u2014 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0430\u0436\u0438\u043C\u0430\u0442\u044C \u043D\u0435 \u043D\u0443\u0436\u043D\u043E.": "2. Read. Your position saves itself on every page turn \u2014 nothing to press.", "3. \u041F\u043E\u043D\u0440\u0430\u0432\u0438\u043B\u0430\u0441\u044C \u043C\u044B\u0441\u043B\u044C \u2014 \u0432\u044B\u0434\u0435\u043B\u044F\u0435\u0442\u0435 \u0435\u0451 \u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0435 \u0446\u0432\u0435\u0442. \u0412\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u043B\u043E\u0441\u044C.": "3. Like a thought \u2014 highlight it and pick a color. The highlight is saved.", "4. (\u043F\u043E \u0436\u0435\u043B\u0430\u043D\u0438\u044E) \u041D\u0430\u0436\u0438\u043C\u0430\u0435\u0442\u0435 \u24D8 \u0432\u0432\u0435\u0440\u0445\u0443 \u0438 \u043F\u0440\u0438\u0432\u044F\u0437\u044B\u0432\u0430\u0435\u0442\u0435 \xAB\u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438\xBB \u2014 \u0441\u0432\u043E\u044E \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 \u0434\u043B\u044F \u044D\u0442\u043E\u0439 \u043A\u043D\u0438\u0433\u0438. \u042D\u0442\u043E \u043C\u043E\u0436\u043D\u043E \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0438 \u043F\u043E\u0442\u043E\u043C.": '4. (optional) Press \u24D8 at the top and link a "book note" \u2014 your page for this book. You can do this later too.', "5. \u041D\u0430\u0436\u0438\u043C\u0430\u0435\u0442\u0435 \u043D\u0430 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u2192 \xAB\u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438\xBB \u2014 \u0446\u0438\u0442\u0430\u0442\u0430 \u0443\u043B\u0435\u0442\u0430\u0435\u0442 \u0432 \u044D\u0442\u0443 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443, \u0438 \u043F\u043B\u0430\u0433\u0438\u043D \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0438\u0442 \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0435\u0451. \u0413\u043E\u0442\u043E\u0432\u043E: \u0432\u0441\u0435 \u0432\u0430\u0448\u0438 \u0446\u0438\u0442\u0430\u0442\u044B \u0432 \u043E\u0434\u043D\u043E\u043C \u043C\u0435\u0441\u0442\u0435.": '5. Tap a highlight \u2192 "to book note" \u2014 the quote flies into that page, and the plugin offers to open it. Done: all your quotes in one place.', "\u0413\u043E\u0442\u043E\u0432\u043E \u2014 \u043F\u0440\u0438\u044F\u0442\u043D\u043E\u0433\u043E \u0447\u0442\u0435\u043D\u0438\u044F!": "All set \u2014 enjoy your reading!", "\u0427\u0442\u043E \u043D\u0430\u0441\u0442\u0440\u043E\u0438\u0442\u044C \u043F\u043E \u0436\u0435\u043B\u0430\u043D\u0438\u044E (\u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E \u0441\u0440\u0430\u0437\u0443): \u043F\u0430\u043F\u043A\u0443 \u0434\u043B\u044F \u043A\u043D\u0438\u0433 \u0438 \u043F\u0430\u043F\u043A\u0443 \u0434\u043B\u044F \u0437\u0430\u043C\u0435\u0442\u043E\u043A \u2014 \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u043F\u043B\u0430\u0433\u0438\u043D\u0430. \u0417\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438 \u2014 \u043F\u043E\u0434 \u0437\u043D\u0430\u0447\u043A\u043E\u043C \u24D8 \u043F\u0440\u044F\u043C\u043E \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0447\u0442\u0435\u043D\u0438\u044F.": "What to set up if you like (not required right away): the books folder and the notes folder \u2014 in the plugin settings. The book note \u2014 under the \u24D8 icon while reading.", "\u0427\u0442\u043E \u043C\u043E\u0436\u043D\u043E \u0432\u043E\u043E\u0431\u0449\u0435 \u043D\u0435 \u0442\u0440\u043E\u0433\u0430\u0442\u044C: \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u0438 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0440\u0430\u0431\u043E\u0442\u0430\u044E\u0442 \u0441\u0440\u0430\u0437\u0443 \u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u0441\u0430\u043C\u0438.": "What you can leave alone entirely: progress and highlights work right away and save themselves.", "\u041F\u043E\u043B\u043D\u0430\u044F \u0441\u043F\u0440\u0430\u0432\u043A\u0430 \u043F\u043E \u043A\u0430\u0436\u0434\u043E\u0439 \u043A\u043D\u043E\u043F\u043A\u0435 \u2014 \u0437\u043D\u0430\u0447\u043E\u043A \u24D8 \u0432 \u0447\u0438\u0442\u0430\u043B\u043A\u0435. \u042D\u0442\u043E\u0442 \u044D\u043A\u0440\u0430\u043D \u043F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u044F \u043C\u043E\u0436\u043D\u043E \u0441\u043D\u043E\u0432\u0430 \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u043F\u043B\u0430\u0433\u0438\u043D\u0430.": "Full help for every button \u2014 the \u24D8 icon in the reader. You can reopen this welcome screen in the plugin settings.", "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 \xAB\u041D\u0430\u0447\u0430\u0442\u044C \u0447\u0438\u0442\u0430\u0442\u044C\xBB \u0438 \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0441\u0432\u043E\u044E \u043F\u0435\u0440\u0432\u0443\u044E \u043A\u043D\u0438\u0433\u0443 \u{1F4D6}": 'Press "Start reading" and open your first book \u{1F4D6}', "\u2039 \u041D\u0430\u0437\u0430\u0434": "\u2039 Back", "\u041D\u0430\u0447\u0430\u0442\u044C \u0447\u0438\u0442\u0430\u0442\u044C": "Start reading", "\u0414\u0430\u043B\u0435\u0435 \u203A": "Next \u203A", "\u041F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u044C": "Skip", "\u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u043C \u043A\u043D\u0438\u0433\u0443\u2026": "Loading the book\u2026", "\u041E\u0448\u0438\u0431\u043A\u0430 \u043F\u0440\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438 \u0444\u0430\u0439\u043B\u0430": "Error opening the file", "\u0421\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0442\u0430\u0439\u043C\u0435\u0440": "Reset timer", "\u0422\u0430\u0439\u043C\u0435\u0440: \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u0434\u043E \u0446\u0435\u043B\u0438 \u2014 \u0441\u0442\u0430\u0440\u0442/\u043F\u0430\u0443\u0437\u0430": "Timer: time left to the goal \u2014 start/pause", "\u041E\u0431\u043D\u043E\u0432\u0438\u0442\u044C (\u043F\u0435\u0440\u0435\u0440\u0438\u0441\u043E\u0432\u0430\u0442\u044C \u0432\u0438\u0434)": "Refresh (redraw the view)", "\u041E\u0433\u043B\u0430\u0432\u043B\u0435\u043D\u0438\u0435": "Table of contents", "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0447\u0442\u0435\u043D\u0438\u044F": "Reading settings", "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u043D\u043E\u0432\u0443\u044E \u0437\u0430\u043C\u0435\u0442\u043A\u0443": "Create new note", "\u0422\u0435\u043A\u0441\u0442\u043E\u043C \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438": "As text into the book note", "\u041D\u0435\u0447\u0435\u0433\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0442\u044C": "Nothing to save", "\u041A\u043D\u0438\u0433\u0430 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u0430": "No book is open", "\u0422\u0435\u043C\u0430": "Theme", "\u0422\u0451\u043C\u043D\u0430\u044F": "Dark", "\u0421\u0432\u0435\u0442\u043B\u0430\u044F": "Light", "\u0421\u0435\u043F\u0438\u044F": "Sepia", "\u0420\u0430\u0437\u043C\u0435\u0440 \u0448\u0440\u0438\u0444\u0442\u0430": "Font size", "\u0428\u0440\u0438\u0444\u0442": "Font", "\u041C\u0435\u0436\u0441\u0442\u0440\u043E\u0447\u043D\u044B\u0439": "Line spacing", "\u0421\u0442\u0440\u0430\u043D\u0438\u0446 \u0440\u044F\u0434\u043E\u043C": "Pages side by side", "1 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0430": "1 page", "2 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B": "2 pages", "\u0412\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u043C\u0435\u0441\u0442\u0443": "Jump back", "\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u044F": "Actions", "\u0422\u043E\u0447\u0435\u043A \u043F\u043E\u043A\u0430 \u043D\u0435\u0442": "No points yet", "\u041D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E": "Unavailable", "\u041D\u0435\u0447\u0435\u0433\u043E \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u0442\u044C": "Nothing to refresh", "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u043E": "Refreshed", "\u041A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0442\u0435\u043A\u0441\u0442": "Copy text", "\u0421\u043A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u043D\u043E \u2713": "Copied \u2713", "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0441\u043A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u0442\u044C": "Could not copy", "\u041E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u0441\u044F \u0437\u0434\u0435\u0441\u044C": "Stopped here", "\u042D\u043A\u0441\u043F\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438": "Export to the book note", "\u0412\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u043E": "Highlight not found", "\u041F\u043E\u043A\u0430 \u043D\u0435\u0442 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439.\n\u0412\u044B\u0434\u0435\u043B\u0438\u0442\u0435 \u0442\u0435\u043A\u0441\u0442 \u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0446\u0432\u0435\u0442.": "No highlights yet.\nSelect text and pick a color.", "\u0423\u0434\u0430\u043B\u0438\u0442\u044C": "Delete", "\u0417\u0430\u043A\u0440\u044B\u0442\u044C": "Close", "\u0411\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430": "Library", "\u041F\u043E\u0438\u0441\u043A \u043A\u043D\u0438\u0433\u0438\u2026": "Search a book\u2026", "\u041C\u0435\u043D\u044C\u0448\u0435 \u043E\u0431\u043B\u043E\u0436\u043A\u0438": "Smaller covers", "\u0411\u043E\u043B\u044C\u0448\u0435 \u043E\u0431\u043B\u043E\u0436\u043A\u0438": "Larger covers", "\u041D\u0435\u0442 \u043A\u043D\u0438\u0433": "No books", "\u0412\u0441\u0435 \u043F\u0430\u043F\u043A\u0438 vault": "All vault folders", "\u043A\u043D\u0438\u0433": "books", "\u043A\u043D\u0438\u0433\u0438": "books", "\u043A\u043D\u0438\u0433\u0430": "book", "\u0412\u0438\u0434 \u043E\u0431\u043B\u043E\u0436\u043A\u0438": "Cover fit", "\u041D\u0435 \u0447\u0438\u0442\u0430\u043B\u0430\u0441\u044C": "Not started", "\u0415\u0449\u0451": "More", "\u041F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0435": "Go to page", "\u041F\u0435\u0440\u0435\u0439\u0442\u0438": "Go", "\u041F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0435 \u0438 \u0438\u043D\u0441\u0442\u0440\u0443\u043A\u0446\u0438\u044F": "Welcome and guide", "\u041F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u0432\u0432\u043E\u0434\u043D\u044B\u0439 \u044D\u043A\u0440\u0430\u043D \u0441 \u043E\u0431\u044A\u044F\u0441\u043D\u0435\u043D\u0438\u0435\u043C \u0444\u043E\u0440\u043C\u0430\u0442\u043E\u0432, \u0437\u0430\u043C\u0435\u0442\u043A\u0438 \u043A\u043D\u0438\u0433\u0438, \u0445\u0440\u0430\u043D\u0435\u043D\u0438\u044F \u0434\u0430\u043D\u043D\u044B\u0445 \u0438 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u0438.": "Show the intro screen explaining formats, the book note, data storage and syncing.", "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0435": "Open welcome", "\u041F\u0430\u043F\u043A\u0430 \u0441 \u043A\u043D\u0438\u0433\u0430\u043C\u0438": "Books folder", "\u041F\u0443\u0441\u0442\u043E = \u0432\u0435\u0441\u044C vault": "Empty = the whole vault", "\u041F\u0430\u043F\u043A\u0430 \u0434\u0430\u043D\u043D\u044B\u0445 \u0447\u0442\u0435\u043D\u0438\u044F": "Reading-data folder", "\u0413\u0434\u0435 \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u0447\u0442\u0435\u043D\u0438\u044F, \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0438 \u0440\u0435\u0437\u0435\u0440\u0432\u043D\u044B\u0435 \u043A\u043E\u043F\u0438\u0438 (reading-progress.json, reading-highlights.json). \u041F\u0443\u0441\u0442\u043E \u2014 \u0440\u044F\u0434\u043E\u043C \u0441 \u043A\u043D\u0438\u0433\u0430\u043C\u0438 (\u0432 \xAB\u041F\u0430\u043F\u043A\u0435 \u0441 \u043A\u043D\u0438\u0433\u0430\u043C\u0438\xBB). \u0424\u0430\u0439\u043B\u044B \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0438\u0440\u0443\u044E\u0442\u0441\u044F \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435\u043C.": 'Where reading progress, highlights and rescue backups are kept (reading-progress.json, reading-highlights.json). Empty \u2014 next to the books (in the "Books folder"). The files sync along with the vault.', "\u0420\u044F\u0434\u043E\u043C \u0441 \u043A\u043D\u0438\u0433\u0430\u043C\u0438": "Next to the books", "\u0417\u0430\u043C\u0435\u0442\u043A\u0438 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439": "Notes from highlights", "\u0428\u0430\u0431\u043B\u043E\u043D \u0437\u0430\u043C\u0435\u0442\u043A\u0438": "Note template", "\u041F\u0443\u0442\u044C \u043A \u0432\u0430\u0448\u0435\u043C\u0443 \u0448\u0430\u0431\u043B\u043E\u043D\u0443 (Templater), \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043F\u0440\u0438\u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u043A \u043D\u043E\u0432\u043E\u0439 \u0437\u0430\u043C\u0435\u0442\u043A\u0435 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F. \u041F\u0443\u0441\u0442\u043E \u2014 \u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u0441\u043E\u0437\u0434\u0430\u0451\u0442\u0441\u044F \u0431\u0435\u0437 \u0448\u0430\u0431\u043B\u043E\u043D\u0430, \u0442\u043E\u043B\u044C\u043A\u043E \u0441 \u0446\u0438\u0442\u0430\u0442\u043E\u0439. \u041F\u0440\u0438\u043C\u0435\u0440: 0. Files/4. Templates/\u0428\u0430\u0431\u043B\u043E\u043D \u0441\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u043D\u044B\u0439.md": "Path to your (Templater) template applied to each new highlight note. Empty \u2014 the note is created without a template, with just the quote. Example: 0. Files/4. Templates/Default template.md", "\u041F\u0430\u043F\u043A\u0430 \u0434\u043B\u044F \u043D\u043E\u0432\u044B\u0445 \u0437\u0430\u043C\u0435\u0442\u043E\u043A": "Folder for new notes", "\u041A\u0443\u0434\u0430 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0438, \u0441\u043E\u0437\u0434\u0430\u0432\u0430\u0435\u043C\u044B\u0435 \u0438\u0437 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439. \u041F\u0443\u0441\u0442\u043E \u2014 \u043A\u043E\u0440\u0435\u043D\u044C \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0430.": "Where to save notes created from highlights. Empty \u2014 the vault root.", "\u041F\u0430\u043F\u043A\u0430 \u0437\u0430\u043C\u0435\u0442\u043E\u043A-\u043A\u043D\u0438\u0433 (\u0434\u043B\u044F \u0441\u0441\u044B\u043B\u043E\u043A)": "Book-notes folder (for links)", "\u0418\u0437 \u044D\u0442\u043E\u0439 \u043F\u0430\u043F\u043A\u0438 \u0431\u0435\u0440\u0451\u0442\u0441\u044F \u0441\u043F\u0438\u0441\u043E\u043A \u043F\u0440\u0438 \u0432\u044B\u0431\u043E\u0440\u0435 \u0437\u0430\u043C\u0435\u0442\u043A\u0438 \u043A\u043D\u0438\u0433\u0438, \u043A\u0443\u0434\u0430 \u0432\u0435\u0434\u0451\u0442 \u0441\u0441\u044B\u043B\u043A\u0430 \xAB\u2014 \u0438\u0437 [[\u2026]]\xBB. \u041F\u0443\u0441\u0442\u043E \u2014 \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043B\u044E\u0431\u0443\u044E \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0430.": 'The list for choosing a book note (where the "\u2014 from [[\u2026]]" link points) is taken from this folder. Empty \u2014 you can pick any note in the vault.', "3. Resources/\u0411\u0430\u0437\u0430 \u043A\u043D\u0438\u0433": "3. Resources/Book base", "\u0421\u043E\u0432\u0435\u0442: \u0448\u0430\u0431\u043B\u043E\u043D \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u043E\u043F\u0440\u0435\u0434\u0435\u043B\u0438\u0442\u044C \u0434\u043B\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0439 \u043A\u043D\u0438\u0433\u0438 \u2014 \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0443, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 (i) \u0432\u0432\u0435\u0440\u0445\u0443 \u0438 \u0443\u043A\u0430\u0436\u0438\u0442\u0435 \u0441\u0432\u043E\u0439 \u0448\u0430\u0431\u043B\u043E\u043D \u0432 \u043F\u043E\u043B\u0435 \xAB\u0428\u0430\u0431\u043B\u043E\u043D \u0434\u043B\u044F \u044D\u0442\u043E\u0439 \u043A\u043D\u0438\u0433\u0438\xBB (\u0443\u0434\u043E\u0431\u043D\u043E, \u0435\u0441\u043B\u0438 \u0443 \u0440\u0430\u0437\u043D\u044B\u0445 \u0436\u0430\u043D\u0440\u043E\u0432 \u0440\u0430\u0437\u043D\u043E\u0435 \u043E\u0444\u043E\u0440\u043C\u043B\u0435\u043D\u0438\u0435).": 'Tip: the template can be overridden per book \u2014 open the book, press (i) at the top and set your template in the "Template for this book" field (handy if different genres need different formatting).', "\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0442\u044C \u0446\u0432\u0435\u0442 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439 \u043F\u0440\u0438 \u044D\u043A\u0441\u043F\u043E\u0440\u0442\u0435": "Keep highlight color on export", "\u041A\u0430\u0436\u0434\u0430\u044F \u0446\u0438\u0442\u0430\u0442\u0430 \u043E\u0431\u043E\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0432 \u0446\u0432\u0435\u0442\u043D\u043E\u0439 <mark> \u2014 \u0446\u0432\u0435\u0442 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0432\u0438\u0434\u0435\u043D \u0432 \u0433\u043E\u0442\u043E\u0432\u043E\u0439 \u0437\u0430\u043C\u0435\u0442\u043A\u0435 (\u0432 \u0440\u0435\u0436\u0438\u043C\u0435 \u0447\u0442\u0435\u043D\u0438\u044F \u0438 live preview, \u0431\u0435\u0437 \u043F\u043B\u0430\u0433\u0438\u043D\u043E\u0432). \u0412\u044B\u043A\u043B\u044E\u0447\u0438\u0442\u0435, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u043E\u0431\u044B\u0447\u043D\u044B\u0435 \u0446\u0438\u0442\u0430\u0442\u044B \u0431\u0435\u0437 HTML.": "Each quote is wrapped in a colored <mark> \u2014 the highlight color shows in the finished note (in reading mode and live preview, no plugins needed). Turn it off if you want plain quotes without HTML.", "\u0414\u0443\u0431\u043B\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 \u043A\u0430\u0440\u0442\u0438\u043D\u043A\u043E\u0439, \u0435\u0441\u043B\u0438 \u0435\u0441\u0442\u044C \u0442\u0435\u043A\u0441\u0442": "Duplicate the page as an image when text exists", "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0412\u042B\u041A\u041B: \u0435\u0441\u043B\u0438 \u0438\u0437 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u0438\u0437\u0432\u043B\u0435\u043A\u0430\u0435\u0442\u0441\u044F \u0442\u0435\u043A\u0441\u0442 \u2014 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0438\u0441\u0442\u044B\u0439 \u0442\u0435\u043A\u0441\u0442, \u0431\u0435\u0437 \u0441\u043A\u0440\u0438\u043D\u0448\u043E\u0442\u0430. \u041A\u0430\u0440\u0442\u0438\u043D\u043A\u0430 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043B\u0438\u0448\u044C \u043A\u043E\u0433\u0434\u0430 \u0442\u0435\u043A\u0441\u0442 \u0438\u0437\u0432\u043B\u0435\u0447\u044C \u043D\u0435\u043B\u044C\u0437\u044F (\u0441\u043A\u0430\u043D\u044B, \u0441\u0445\u0435\u043C\u044B, \u043E\u0431\u043B\u043E\u0436\u043A\u0438). \u0412\u043A\u043B\u044E\u0447\u0438\u0442\u0435, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u0412\u0418\u0414\u0415\u0422\u042C \u043E\u0440\u0438\u0433\u0438\u043D\u0430\u043B\u044C\u043D\u044B\u0439 \u0440\u0438\u0441\u0443\u043D\u043E\u043A \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u043D\u0430\u0434 \u0442\u0435\u043A\u0441\u0442\u043E\u043C (\u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0434\u043B\u044F \u043A\u043D\u0438\u0433-\u0441\u043A\u0435\u0442\u0447\u043D\u043E\u0443\u0442\u043E\u0432). \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0443 \u0437\u0430\u043D\u043E\u0432\u043E, \u0447\u0442\u043E\u0431\u044B \u043F\u0440\u0438\u043C\u0435\u043D\u0438\u0442\u044C.": "OFF by default: if text can be extracted from the page, only the clean text is shown, without a screenshot. The image is shown only when text can't be extracted (scans, diagrams, covers). Turn it on if you want to SEE the original page image above the text (for example, for sketchnote books). Reopen the book to apply.", "\u041B\u0438\u0441\u0442\u0430\u043D\u0438\u0435 \u0441\u0442\u0440\u0430\u043D\u0438\u0446": "Page turning", "\xAB\u041A\u043D\u043E\u043F\u043A\u0430\u043C\u0438\xBB \u2014 \u0441\u0442\u0440\u0435\u043B\u043A\u0438/\u043A\u043B\u0430\u0432\u0438\u0448\u0438/\u0441\u0432\u0430\u0439\u043F. \xAB\u041F\u043E \u043A\u043B\u0438\u043A\u0443\xBB \u2014 \u043A\u043B\u0438\u043A \u043F\u043E \u043B\u0435\u0432\u043E\u0439/\u043F\u0440\u0430\u0432\u043E\u0439 \u0447\u0430\u0441\u0442\u0438 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u043B\u0438\u0441\u0442\u0430\u0435\u0442 \u043D\u0430\u0437\u0430\u0434/\u0432\u043F\u0435\u0440\u0451\u0434 (\u0446\u0435\u043D\u0442\u0440 \u0441\u0432\u043E\u0431\u043E\u0434\u0435\u043D \u0434\u043B\u044F \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0442\u0435\u043A\u0441\u0442\u0430).": '"Buttons" \u2014 arrows/keys/swipe. "By click" \u2014 clicking the left/right part of the page turns back/forward (the center stays free for selecting text).', "\u041F\u043E \u043A\u043B\u0438\u043A\u0443 \u043C\u044B\u0448\u043A\u043E\u0439": "By mouse click", "\u0422\u0430\u0439\u043C\u0435\u0440 \u0446\u0435\u043B\u0438 \u0447\u0442\u0435\u043D\u0438\u044F": "Reading-goal timer", "\u041E\u0431\u0440\u0430\u0442\u043D\u044B\u0439 \u043E\u0442\u0441\u0447\u0451\u0442 \u0434\u043E \u0434\u043D\u0435\u0432\u043D\u043E\u0439 \u0446\u0435\u043B\u0438 (\u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, 15 \u043C\u0438\u043D\u0443\u0442) \u2014 \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0435\u0449\u0451 \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C. \u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F \u0412\u0420\u0423\u0427\u041D\u0423\u042E \u043A\u043D\u043E\u043F\u043A\u043E\u0439 \u25B6 \u0432\u0432\u0435\u0440\u0445\u0443 \u0447\u0438\u0442\u0430\u043B\u043A\u0438, \u0440\u044F\u0434\u043E\u043C \u0441 \xAB\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C\xBB (\u043F\u0430\u0443\u0437\u0430 \u2014 \u23F8).": 'A countdown to your daily goal (for example, 15 minutes) \u2014 how much is left to read. Started MANUALLY with the \u25B6 button at the top of the reader, next to "Save" (pause \u2014 \u23F8).', "\u0426\u0435\u043B\u044C \u043D\u0430 \u0434\u0435\u043D\u044C, \u043C\u0438\u043D\u0443\u0442": "Daily goal, minutes", "\u041F\u043E\u0433\u0440\u0443\u0436\u0435\u043D\u0438\u0435 (Immersive)": "Immersive", "\u041F\u0430\u043D\u0435\u043B\u0438 \u0441\u0432\u0435\u0440\u0445\u0443 \u0438 \u0441\u043D\u0438\u0437\u0443 \u043C\u044F\u0433\u043A\u043E \u043F\u0440\u0438\u0442\u0443\u0445\u0430\u044E\u0442 \u0447\u0435\u0440\u0435\u0437 \u043F\u0430\u0440\u0443 \u0441\u0435\u043A\u0443\u043D\u0434 \u0431\u0435\u0437 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u043C\u044B\u0448\u0438 \u0438 \u043C\u0433\u043D\u043E\u0432\u0435\u043D\u043D\u043E \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u044E\u0442\u0441\u044F \u043F\u0440\u0438 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0438 \u2014 \u0447\u0442\u043E\u0431\u044B \u043D\u0438\u0447\u0442\u043E \u043D\u0435 \u043E\u0442\u0432\u043B\u0435\u043A\u0430\u043B\u043E \u043E\u0442 \u0442\u0435\u043A\u0441\u0442\u0430.": "The top and bottom bars gently dim after a couple of seconds without mouse movement and instantly return when you move \u2014 so nothing distracts from the text.", "\u041A\u044D\u0448 \u043E\u0431\u043B\u043E\u0436\u0435\u043A": "Cover cache", "\u041E\u0447\u0438\u0441\u0442\u0438\u0442\u044C": "Clear", "\u041A\u044D\u0448 \u043E\u0447\u0438\u0449\u0435\u043D": "Cache cleared", "\u041F\u0440\u043E\u0433\u0440\u0435\u0441\u0441": "Progress", "\u041F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u043E\u0447\u0438\u0449\u0435\u043D": "Progress cleared", "\u041E\u0447\u0438\u0441\u0442\u0438\u0442\u044C \u0432\u0441\u0435": "Clear all", "\u0412\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u043E\u0447\u0438\u0449\u0435\u043D\u044B": "Highlights cleared", "\u0421\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u044F \u043C\u0435\u0436\u0434\u0443 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430\u043C\u0438": "Syncing across devices", "\u0421\u043F\u043E\u0441\u043E\u0431 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u0438": "Sync method", "\u041F\u043E\u0434\u0441\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u043F\u043B\u0430\u0433\u0438\u043D\u0443, \u043D\u0430\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u0432\u0435\u0436\u043E \u043F\u0435\u0440\u0435\u0447\u0438\u0442\u044B\u0432\u0430\u0442\u044C \u0444\u0430\u0439\u043B\u044B \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441\u0430 \u043F\u0440\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438 \u043A\u043D\u0438\u0433\u0438.": "Tells the plugin how eagerly to re-read the progress files when opening a book.", "\u0410\u0432\u0442\u043E (\u0440\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0443\u0435\u0442\u0441\u044F)": "Auto (recommended)", "iCloud / Google Drive / \u043F\u0430\u043F\u043A\u0430": "iCloud / Google Drive / folder", "\u0411\u0435\u0437 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u0438": "No syncing", "\u041E\u0431\u043B\u0430\u0447\u043D\u044B\u0435 \u043F\u0430\u043F\u043A\u0438 (iCloud/Drive) \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0441 \u0437\u0430\u0434\u0435\u0440\u0436\u043A\u043E\u0439. \u0415\u0441\u043B\u0438 \u043D\u0430 \u043E\u0434\u043D\u043E\u043C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435 \u0432\u044B \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0438\u0442\u0430\u0435\u0442\u0435 \u2014 \u043A\u043E\u043D\u0444\u043B\u0438\u043A\u0442\u043E\u0432 \u043D\u0435 \u0431\u0443\u0434\u0435\u0442: \u043F\u043B\u0430\u0433\u0438\u043D \u043F\u0435\u0440\u0435\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u043F\u0440\u0438 \u043A\u0430\u0436\u0434\u043E\u043C \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438 \u043A\u043D\u0438\u0433\u0438 \u0438 \u0430\u043A\u043A\u0443\u0440\u0430\u0442\u043D\u043E \u0441\u043B\u0438\u0432\u0430\u0435\u0442 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F.": "Cloud folders (iCloud/Drive) update with a delay. If you only read on one device there will be no conflicts: the plugin re-reads progress every time a book is opened and carefully merges highlights.", "\u2713 \u0426\u0435\u043B\u044C \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0442\u0430 \u2014 {0} \u043C\u0438\u043D \u0441\u0435\u0433\u043E\u0434\u043D\u044F": "\u2713 Goal reached \u2014 {0} min today", "\u23F1 {0} \u0438\u0437 {1} \u043C\u0438\u043D \xB7 {2}%": "\u23F1 {0} of {1} min \xB7 {2}%", "{0} \u043C\u0438\u043D/\u0434\u0435\u043D\u044C": "{0} min/day", "\u0421\u0435\u0433\u043E\u0434\u043D\u044F \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u043D\u043E: {0} \u043C\u0438\u043D. \u041A\u043D\u043E\u043F\u043A\u0430 \u25B6 \u0432\u0432\u0435\u0440\u0445\u0443 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u043E\u0431\u0440\u0430\u0442\u043D\u044B\u0439 \u043E\u0442\u0441\u0447\u0451\u0442 \u0434\u043E \u0446\u0435\u043B\u0438 (\u043F\u0430\u0443\u0437\u0430 \u2014 \u23F8).": "Read today: {0} min. The \u25B6 button at the top starts the countdown to the goal (pause \u2014 \u23F8).", "\n\n\u2014 \u0438\u0437 [[{0}]]": "\n\n\u2014 from [[{0}]]", "\u0412\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u2014 {0}": "Highlights \u2014 {0}", '---\ncreated: {0}\nsource: "[[{1}]]"\ntags: [\u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F]\n---\n\n# {2}\n\n{3}\n\n\u2014 \u0438\u0437 [[{4}]]\n': '---\ncreated: {0}\nsource: "[[{1}]]"\ntags: [highlights]\n---\n\n# {2}\n\n{3}\n\n\u2014 from [[{4}]]\n', "\u042D\u043A\u0441\u043F\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u043D\u043E \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439: {0}": "Highlights exported: {0}", "\u0421\u043E\u0437\u0434\u0430\u044E \u0437\u0430\u043C\u0435\u0442\u043A\u0438: {0}\u2026": "Creating notes: {0}\u2026", "\u0421\u043E\u0437\u0434\u0430\u043D\u043E \u0437\u0430\u043C\u0435\u0442\u043E\u043A: {0}, \u043E\u0448\u0438\u0431\u043E\u043A: {1}": "Notes created: {0}, errors: {1}", "\u0421\u043E\u0437\u0434\u0430\u043D\u043E \u0437\u0430\u043C\u0435\u0442\u043E\u043A: {0}": "Notes created: {0}", "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u043A\u043D\u0438\u0433\u0438 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u0430: {0}": "Book note not found: {0}", "\u0414\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043E \u0446\u0438\u0442\u0430\u0442 \u0432 \xAB{0}\xBB: {1}": 'Quotes added to "{0}": {1}', "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \xAB{0}\xBB \u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0439 \u0432\u043A\u043B\u0430\u0434\u043A\u0435?": 'Open the note "{0}" in a separate tab?', "\u041E\u0442\u0434\u0435\u043B\u044C\u043D\u0430\u044F \u0437\u0430\u043C\u0435\u0442\u043A\u0430 \u043D\u0430 \u043A\u0430\u0436\u0434\u043E\u0435 ({0})": "A separate note for each ({0})", "\u0422\u0435\u043A\u0441\u0442\u043E\u043C \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0443 \u043A\u043D\u0438\u0433\u0438 ({0})": "As text into the book note ({0})", "\u041D\u0435\u0442 \u0437\u0430\u043C\u0435\u0442\u043E\u043A \u0432 \xAB{0}\xBB": 'No notes in "{0}"', "\u0417\u0430\u043C\u0435\u0442\u043A\u0430 \u043A\u043D\u0438\u0433\u0438: {0}": "Book note: {0}", "\u0428\u0430\u0431\u043B\u043E\u043D \u043A\u043D\u0438\u0433\u0438: {0}": "Book template: {0}", "\u042D\u043A\u0440\u0430\u043D {0}": "Screen {0}", "\u0413\u043E\u0442\u043E\u0432\u0438\u043C \u043A\u043D\u0438\u0433\u0443\u2026 {0}%": "Preparing the book\u2026 {0}%", "\u0412\u044B\u0434\u0435\u043B\u0438\u0442\u044C: {0}": "Highlight: {0}", "\u0421\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u043E \u2713 \u2014 {0}%": "Saved \u2713 \u2014 {0}%", "\u0420\u0430\u0437\u0432\u043E\u0440\u043E\u0442 {0} \u0438\u0437 {1}": "Spread {0} of {1}", "\u0412\u0435\u0440\u043D\u0443\u043B\u0438\u0441\u044C \u043A {0}%": "Jumped back to {0}%", "\u0417\u0430\u043A\u043B\u0430\u0434\u043A\u0430 \xAB\u043E\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u043B\u0441\u044F \u0437\u0434\u0435\u0441\u044C\xBB \u2014 {0}%": '"Stopped here" bookmark \u2014 {0}%', "{0}<span>\u042D\u043A\u0441\u043F\u043E\u0440\u0442\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0432 \u0437\u0430\u043C\u0435\u0442\u043A\u0438 ({1})</span>": "{0}<span>Export to notes ({1})</span>", '<p style="padding:40px;color:var(--er-muted);margin:auto;">\u041E\u0448\u0438\u0431\u043A\u0430: {0}</p>': '<p style="padding:40px;color:var(--er-muted);margin:auto;">Error: {0}</p>', "{0}<span>\u0421\u043F\u0440\u0430\u0432\u043A\u0430</span>": "{0}<span>Help</span>", "\u0421\u0435\u0433\u043E\u0434\u043D\u044F \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u043D\u043E: {0} \u043C\u0438\u043D.": "Read today: {0} min.", "\u0421\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u043E: {0}": "Saved: {0}", "\u041A\u043D\u0438\u0433: {0}": "Books: {0}", "\u0412\u0441\u0435\u0433\u043E: {0}": "Total: {0}", "\u041F\u0440\u043E\u0433\u0440\u0435\u0441\u0441 \u0447\u0442\u0435\u043D\u0438\u044F \u0438 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u044F \u0445\u0440\u0430\u043D\u044F\u0442\u0441\u044F <b>\u0444\u0430\u0439\u043B\u0430\u043C\u0438 \u043F\u0440\u044F\u043C\u043E \u0432 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435</b>, \u0440\u044F\u0434\u043E\u043C \u0441 \u043A\u043D\u0438\u0433\u0430\u043C\u0438:": "Reading progress and highlights are stored <b>as files right in the vault</b>, next to the books:", "\u041F\u043E\u044D\u0442\u043E\u043C\u0443 \u043E\u043D\u0438 \u043F\u0435\u0440\u0435\u0435\u0437\u0436\u0430\u044E\u0442 \u043C\u0435\u0436\u0434\u0443 \u041F\u041A \u0438 \u0442\u0435\u043B\u0435\u0444\u043E\u043D\u043E\u043C <b>\u043B\u044E\u0431\u044B\u043C</b> \u0441\u043F\u043E\u0441\u043E\u0431\u043E\u043C, \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u0432\u044B \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0438\u0440\u0443\u0435\u0442\u0435 \u0441\u0430\u043C\u043E \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0435 ": "So they travel between PC and phone by <b>any</b> means you use to sync the vault itself ", "(Obsidian Sync, iCloud, Google Drive, Remotely Save \u0438 \u0442.\u043F.). \u041F\u0440\u0438\u0432\u044F\u0437\u043A\u0430 \u043A \u043C\u0435\u0441\u0442\u0443 \u2014 \u043F\u043E \u043D\u043E\u043C\u0435\u0440\u0443 \u0430\u0431\u0437\u0430\u0446\u0430, ": "(Obsidian Sync, iCloud, Google Drive, Remotely Save, etc.). The position is anchored by paragraph number, ", "\u0442\u0430\u043A \u0447\u0442\u043E \u041F\u041A \u0438 \u0442\u0435\u043B\u0435\u0444\u043E\u043D \u043D\u0430\u0445\u043E\u0434\u044F\u0442 \u043E\u0434\u043D\u0443 \u0438 \u0442\u0443 \u0436\u0435 \u0442\u043E\u0447\u043A\u0443 \u043F\u0440\u0438 \u043B\u044E\u0431\u043E\u043C \u0440\u0430\u0437\u043C\u0435\u0440\u0435 \u044D\u043A\u0440\u0430\u043D\u0430.<br>": "so PC and phone find the same spot at any screen size.<br>", "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043E\u0444\u043E\u0440\u043C\u043B\u0435\u043D\u0438\u044F \u0438 \u043A\u044D\u0448 \u043E\u0431\u043B\u043E\u0436\u0435\u043A \u2014 \u043B\u043E\u043A\u0430\u043B\u044C\u043D\u044B\u0435 (\u0432 <code>data.json</code> \u043F\u043B\u0430\u0433\u0438\u043D\u0430) \u0438 \u043D\u0430\u043C\u0435\u0440\u0435\u043D\u043D\u043E \u043D\u0435 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0438\u0440\u0443\u044E\u0442\u0441\u044F.": "Appearance settings and the cover cache are local (in the plugin's <code>data.json</code>) and are intentionally not synced.", "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u043A\u043D\u0438\u0433\u0443": "Add a book", "\u041E\u0442\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u0444\u0430\u0439\u043B\u044B, \u0447\u0442\u043E\u0431\u044B \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0438\u0445 \u0432 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443": "Drop the files to add them to your library", "\u041F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0444\u0430\u0439\u043B\u044B PDF, EPUB \u0438 FB2": "Only PDF, EPUB and FB2 files are supported", "\u0424\u0430\u0439\u043B\u044B \u043D\u0435 \u0432\u044B\u0431\u0440\u0430\u043D\u044B": "No files selected", "\u0414\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043E \u043A\u043D\u0438\u0433: {0}": "Books added: {0}", "\u043F\u0440\u043E\u043F\u0443\u0449\u0435\u043D\u043E: {0}": "skipped: {0}", "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C: {0}": "Could not add: {0}", "\u0410\u0431\u0437\u0430\u0446\u044B \u0432 PDF \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u043A\u0430\u043A \u0432 \u043E\u0440\u0438\u0433\u0438\u043D\u0430\u043B\u0435 \u2014 \u0442\u0435\u043A\u0441\u0442 \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u0441\u043A\u043B\u0435\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0432 \u0441\u043F\u043B\u043E\u0448\u043D\u0443\u044E \u0441\u0442\u0435\u043D\u0443": "PDF paragraphs are kept as in the original \u2014 the text no longer glues into one solid wall", "\u0411\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430: \u043A\u043D\u043E\u043F\u043A\u0430 \xAB\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u043A\u043D\u0438\u0433\u0443\xBB \u0438 \u043F\u0435\u0440\u0435\u0442\u0430\u0441\u043A\u0438\u0432\u0430\u043D\u0438\u0435 \u0444\u0430\u0439\u043B\u043E\u0432 (PDF, EPUB, FB2) \u043F\u0440\u044F\u043C\u043E \u0432 \u043E\u043A\u043D\u043E": 'Library: an "Add a book" button and drag-and-drop of files (PDF, EPUB, FB2) straight into the window', "PDF-\u0434\u0432\u0438\u0436\u043E\u043A \u0432\u0441\u0442\u0440\u043E\u0435\u043D \u0432 \u043F\u043B\u0430\u0433\u0438\u043D \u2014 \u043A\u043D\u0438\u0433\u0438 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043E\u0444\u043B\u0430\u0439\u043D, \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043F\u043E\u0434\u0433\u0440\u0443\u0436\u0430\u0435\u0442\u0441\u044F \u0438\u0437 \u0438\u043D\u0442\u0435\u0440\u043D\u0435\u0442\u0430": "The PDF engine is now bundled in \u2014 books open offline, nothing is fetched from the internet", "\u0412 \u0441\u043F\u0438\u0441\u043A\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0439 \u043A\u043E\u043C\u043C\u0435\u043D\u0442\u0430\u0440\u0438\u0439 \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u043B\u043E\u043C\u0430\u0435\u0442 \u0446\u0438\u0442\u0430\u0442\u0443 \u2014 \u043E\u043D \u0430\u043A\u043A\u0443\u0440\u0430\u0442\u043D\u043E \u0432\u0441\u0442\u0430\u0451\u0442 \u043F\u043E\u0434 \u043D\u0435\u0439": "In the highlights list a comment no longer breaks the quote \u2014 it sits neatly underneath it" };
